'use strict';
const $=s=>document.querySelector(s), app=$('#app');
const refs=['디모데후서 3:16–17','여호수아 1:8','요한복음 16:24','요한계시록 1:8','주기도문','마태복음 16:16','사도신경','로마서 5:8','요한복음 7:37–38','에베소서 2:8','마태복음 22:37–38','마태복음 22:39','요한일서 2:17','고린도전서 15:57–58','에베소서 4:3–4'];
const lessons=[1,2,3,4,4,5,5,6,7,8,9,10,11,12,13];
const activeKeys=[0,1,2,3,5,7,8,9,10,11,12,13,14];const officialIds=new Set(activeKeys.map(i=>'yes-'+i));
const uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const initial=()=>({schema:1,theme:'system',goal:3,plans:[{id:'yes',title:'새일꾼반'}],items:activeKeys.map(i=>({id:'yes-'+i,plan:'yes',lesson:lessons[i],ref:refs[i],text:'',translation:'개역개정',lang:'ko-KR',favorite:false,notes:'',version:1})),attempts:[],reviews:{},trash:[],audio:{rate:1,repeat:3,gap:5,reference:true,shuffle:false,timer:0},listening:0});
function normalizeCurriculum(d){if(!d||!Array.isArray(d.items))return false;let before=d.items.length;d.items=d.items.filter(x=>!(x.plan==='yes'&&['yes-4','yes-6'].includes(x.id)));let changed=before!==d.items.length;let official=d.plans?.find(p=>p.id==='yes');if(official&&!Number.isInteger(official.activeThrough)){official.activeThrough=Math.min(13,Math.max(1,...d.items.filter(x=>x.plan==='yes'&&(d.reviews?.[x.id]||d.attempts?.some(a=>a.item===x.id))).map(x=>x.lesson||1)));changed=true}for(let x of initial().items){if(!d.items.some(y=>y.id===x.id)){d.items.push(x);changed=true}}let current=d.items.filter(x=>x.plan==='yes'&&officialIds.has(x.id));let ordered=current.slice().sort((a,b)=>a.lesson-b.lesson);if(current.some((x,i)=>x!==ordered[i])){d.items=[...ordered,...d.items.filter(x=>!current.includes(x))];changed=true}return changed}
const identity=window.YES_IDENTITY;if(!identity?.id)throw Error('Authentication required');const isGuest=identity.guest===true;const storageKey='yes-word-v1:'+identity.id;let db;try{db=JSON.parse(localStorage.getItem(storageKey))||initial();if(db.schema!==1||!Array.isArray(db.items)||!Array.isArray(db.plans)||!Array.isArray(db.attempts))throw Error()}catch{db=initial()}db.profile=isGuest?{...identity.profile,...db.profile,id:identity.id}:{...identity.profile};
function save(){normalizeCurriculum(db);try{localStorage.setItem(storageKey,JSON.stringify(db));syncSchedule()}catch(e){toast('저장 공간이 부족합니다. 백업해 주세요.')}}
/* v0.6: private, revision-checked cloud snapshots. No audio blobs or auth tokens. */
const syncKey=storageKey+':cloud-meta', conflictKey=storageKey+':cloud-conflict-backup';
let syncMeta={enabled:false,revision:null,digest:null}, syncBusy=false,syncTimer=null,syncMessage='클라우드 백업을 아직 시작하지 않았습니다.';
try{let m=JSON.parse(localStorage.getItem(syncKey));if(m&&typeof m.enabled==='boolean')syncMeta=m}catch{}
function cloudData(){let {schema,theme,goal,plans,items,attempts,reviews,trash,audio,listening,preferences}=db;return {schema,theme,goal,plans,items,attempts,reviews,trash,audio,listening,preferences}}
function canonical(x){if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().filter(k=>x[k]!==undefined).map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';return JSON.stringify(x)}
async function digest(x){let bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(x)));return Array.from(new Uint8Array(bytes),n=>n.toString(16).padStart(2,'0')).join('')}
function validSnapshot(x){const safeId=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,128}$/.test(v), obj=v=>v&&typeof v==='object'&&!Array.isArray(v), text=v=>typeof v==='string', itemOK=i=>obj(i)&&safeId(i.id)&&safeId(i.plan)&&text(i.ref)&&text(i.text)&&(!i.notes||text(i.notes));return obj(x)&&x.schema===1&&Array.isArray(x.plans)&&x.plans.every(p=>obj(p)&&safeId(p.id)&&text(p.title))&&Array.isArray(x.items)&&x.items.every(itemOK)&&Array.isArray(x.trash)&&x.trash.every(itemOK)&&Array.isArray(x.attempts)&&x.attempts.every(a=>obj(a)&&safeId(a.item)&&Number.isFinite(a.time))&&obj(x.reviews)&&obj(x.audio)&&Number.isFinite(x.goal)&&Number.isFinite(x.listening)&&['light','dark','system'].includes(x.theme)&&new TextEncoder().encode(JSON.stringify(x)).length<=1800000}
function nonempty(x){return x.items.some(i=>(i.plan!=='yes'&&i.text.trim())||i.favorite||i.notes)||x.attempts.length||x.plans.length>1||x.trash.length||x.items.length!==activeKeys.length||x.items.some(i=>!officialIds.has(i.id))}
function cloudStatus(msg){syncMessage=msg;let e=$('#cloud-status');if(e)e.textContent=msg}
function persistSync(m){localStorage.setItem(syncKey,JSON.stringify(m));syncMeta=m}
function syncSchedule(){if(!syncMeta.enabled||syncBusy||syncMeta.revision===null||!window.YES_CLIENT||!navigator.onLine)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloud('auto'),1200)}
function syncPanel(){if(isGuest)return '<section class="card stack"><h3>기기 저장 모드</h3><p>게스트 기록은 이 기기에만 저장됩니다. 브라우저 데이터를 삭제하면 사라질 수 있습니다.</p>'+btn('Google 로그인으로 전환','guestlogin','primary full')+'</section>';return '<section class="card stack"><h3>클라우드 동기화</h3><p id="cloud-status" role="status">'+esc(syncMessage)+'</p><small>말씀, 플랜, 묵상 노트, 학습 기록 및 설정을 내 계정에만 저장합니다. 녹음은 이 기기에 남습니다. 처음 동기화하기 전에는 서버로 전송하지 않습니다.</small>'+btn('지금 동기화','cloudsync','primary full')+btn(syncMeta.enabled?'자동 백업 끄기':'자동 백업 켜기','cloudtoggle','outline full')+btn('서버 기록 사용 (충돌 해결)','cloudpull','outline full')+btn('이 기기 기록 사용 (충돌 해결)','cloudpush','outline full')+(localStorage.getItem(conflictKey)?btn('충돌 이전 기록 다운로드','cloudconflictbackup','outline full'):'')+'</section>'}
async function syncCloud(mode='manual'){
 if(syncBusy)return;if(!window.YES_CLIENT||!navigator.onLine){cloudStatus('오프라인입니다. 학습 기록은 기기에 저장됩니다.');return}
 syncBusy=true;clearTimeout(syncTimer);let c=window.YES_CLIENT;cloudStatus('동기화 확인 중…');
 try{
  let local=JSON.parse(JSON.stringify(cloudData()));if(!validSnapshot(local))throw Error('저장 데이터 형식 또는 용량을 확인하세요.');
  let localHash=await digest(local),q=await c.from('learning_snapshots').select('payload,revision,updated_at').eq('user_id',identity.id).maybeSingle();
  if(q.error)throw q.error;let remote=q.data,rev=remote?Number(remote.revision):null;
  if(remote&&(!validSnapshot(remote.payload)||!Number.isSafeInteger(rev)||rev<1))throw Error('서버 기록 형식을 확인할 수 없습니다.');
  let remoteHash=remote?await digest(remote.payload):null;
  let localChanged=syncMeta.digest!==localHash,remoteChanged=syncMeta.revision!==rev;
  let finish=(revision,hash)=>{persistSync({...syncMeta,revision,digest:hash});cloudStatus('동기화 완료 · '+new Date().toLocaleString('ko-KR'))};
  if(remoteHash===localHash){finish(rev,localHash);return}
  if(mode==='auto'&&(remoteChanged||!remote)){cloudStatus('다른 기기에서 변경되었거나 서버 기록이 없습니다. MY에서 지금 동기화해 주세요.');return}
  let pull=mode==='pull'||(mode==='manual'&&remote&&((syncMeta.revision===null&&!nonempty(local))||(!localChanged&&remoteChanged)));
  let push=mode==='push'||(!remote&&mode==='manual')||(!remoteChanged&&localChanged&&syncMeta.revision!==null);
  if(pull){
   if(!remote)throw Error('서버에 저장된 기록이 없습니다.');
   if(page!=='my')throw Error('MY 화면에서 다시 시도하세요.');
   if(!confirm('서버 기록을 이 기기에 적용할까요? 현재 기록은 충돌 백업으로 보존됩니다.')){cloudStatus('동기화 취소');return}
   if(await digest(cloudData())!==localHash||page!=='my')throw Error('현재 기록이 변경되었습니다. 다시 시도하세요.');
   localStorage.setItem(conflictKey,JSON.stringify(local));
   let next={...initial(),...remote.payload,profile:db.profile};localStorage.setItem(storageKey,JSON.stringify(next));db=next;theme();finish(rev,remoteHash);render();return
  }
  if(!push){cloudStatus('두 기기의 기록이 다릅니다. 서버 기록 또는 이 기기 기록을 선택하세요. 자동 덮어쓰기는 하지 않습니다.');return}
  if(mode==='push'&&remote){if(!confirm('이 기기의 기록으로 서버 기록을 교체할까요? 서버의 기존 기록은 이 기기에 별도 백업됩니다.')){cloudStatus('동기화 취소');return}localStorage.setItem(conflictKey,JSON.stringify(remote.payload))}
  if(!remote&&mode==='manual'&&!confirm('이 계정의 말씀 및 학습 기록을 클라우드에 처음 저장할까요?')){cloudStatus('동기화 취소');return}
  if(await digest(cloudData())!==localHash)throw Error('학습 기록이 변경되었습니다. 다시 시도하세요.');
  let write=remote?await c.from('learning_snapshots').update({payload:local,revision:rev+1}).eq('user_id',identity.id).eq('revision',rev).select('revision').maybeSingle():await c.from('learning_snapshots').insert({user_id:identity.id,payload:local,revision:1}).select('revision').single();
  if(write.error)throw write.error;if(!write.data)throw Error('다른 기기에서 변경되었습니다. 다시 동기화하세요.');
  finish(Number(write.data.revision),localHash);
 }catch(e){cloudStatus('동기화 실패 · '+(e.code==='42P01'||e.code==='PGRST205'?'서버 DB 설정이 아직 완료되지 않았습니다.':e.message||'다시 시도하세요.'))}
 finally{syncBusy=false}
}

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let weeklyConfig={from:1,through:2};try{let w=JSON.parse(localStorage.getItem('yw-weekly-public'));if(Number.isInteger(w?.from)&&Number.isInteger(w?.through)&&w.from>=1&&w.through<=13&&w.from<=w.through)weeklyConfig=w}catch{}
const classSchedule=Array.from({length:12},(_,i)=>({week:i+1,from:i===0?1:i+2,through:i+2,reading:i<10?'요한복음 '+(i*2+1)+'~'+(i*2+2)+'장':i===10?'요한복음 21장':''}));
function classWeek(){return Math.max(1,Math.min(12,weeklyConfig.through-1))}
function progressPlan(){return db.plans.find(p=>p.id==='yes')}
function personalWeek(){let p=progressPlan();if(p?.weekMode==='manual'&&Number.isInteger(p.selectedWeek))return Math.max(1,Math.min(12,p.selectedWeek));if(p?.weekMode==='follow')return classWeek();return Math.max(classWeek(),Math.min(12,(p?.activeThrough||2)-1))}
function focusWeek(){let p=progressPlan(),w=personalWeek();return p?.weekMode==='manual'||w!==classWeek()?classSchedule[w-1]:{...classSchedule[w-1],from:weeklyConfig.from,through:weeklyConfig.through}}
function currentWeek(){return classSchedule[personalWeek()-1].through}
function inStudy(x){return x.plan!=='yes'||x.lesson<=currentWeek()}
function weeklyItems(){return db.items.filter(x=>x.plan==='yes'&&inStudy(x))}
function focusItems(){let w=focusWeek();return weeklyItems().filter(x=>x.lesson>=w.from&&x.lesson<=w.through)}
function selectStudyWeek(value){let p=progressPlan();if(!p)return;let old=personalWeek();let n=value==='follow'?classWeek():Math.max(1,Math.min(12,Number(value)||1));if(n<old&&!confirm('이전 주차로 이동할까요? 암송 기록과 노트는 삭제되지 않습니다.'))return;p.weekMode=value==='follow'?'follow':'manual';p.selectedWeek=n;p.activeThrough=classSchedule[n-1].through;save();render();toast(n+'주차 학습 범위 설정 완료')}
function readingDone(){return progressPlan()?.readingDone?.includes(personalWeek())||false}
function toggleReading(){let p=progressPlan();if(!p)return;let w=personalWeek(),list=Array.isArray(p.readingDone)?p.readingDone:[];p.readingDone=list.includes(w)?list.filter(x=>x!==w):[...list,w];save();render()}
function progressSelector(){let p=progressPlan(),w=personalWeek(),configured=!!p?.weekMode;let val=p?.weekMode==='follow'||(!configured&&w===classWeek())?'follow':String(w);return '<section class="card stack yw-week-picker"><div class="row between"><h3 style="margin:0">'+(configured?'나의 수업 진도':'어느 주차를 배우고 있나요?')+'</h3><span class="pill">'+w+'주차</span></div><small class="muted">'+(configured?'중간에 참여하거나 복습할 때 언제든 변경할 수 있어요.':'현재 수업 진도를 선택하고 바로 시작하세요. 나중에도 변경할 수 있습니다.')+'</small><label for="week-select">수업 주차</label><div class="row"><select id="week-select">'+options([['follow','수업 진도 따라가기 · '+classWeek()+'주차'],...classSchedule.map(x=>[String(x.week),x.week+'주차 · '+(x.from===x.through?x.from:x.from+'~'+x.through)+'과'])],val)+'</select>'+btn(configured?'적용':'시작','weekset','primary')+'</div>'+(configured?'':'<small>기본값은 관리자가 설정한 현재 수업입니다.</small>')+'</section>'}
const day=(d=Date.now())=>new Date(d).toLocaleDateString('sv-SE'); 

