function translateLabel(v){if(preferences().ui!=='en')return v;let raw=String(v),t=raw.trim();if(Object.prototype.hasOwnProperty.call(uiEnglish,t))return raw.replace(t,uiEnglish[t]);let m=t.match(/^(\d+)주차(?: · (\d+(?:~\d+)?)과)?$/);if(m)return 'Week '+m[1]+(m[2]?' · Lesson '+m[2]:'');m=t.match(/^(\d+(?:~\d+)?)과(?: · (암송 완료|암송 연습))?$/);if(m)return 'Lesson '+m[1]+(m[2]?' · '+(m[2]==='암송 완료'?'Memorized':'Practice'):'');m=t.match(/^(\d+)(문제|회|초|개|분|점)$/);if(m)return m[1]+({'문제':' questions','회':' times','초':' sec','개':' verses','분':' min','점':' points'}[m[2]]);m=t.match(/^(.*?) \((\d+)개\)$/);if(m&&uiEnglish[m[1]])return uiEnglish[m[1]]+' ('+m[2]+')';return raw}
function localizeChrome(){const navLabels={home:['홈','Home'],plans:['플랜','Plans'],study:['암송','Practice'],listen:['듣기','Listen'],my:['MY','MY']};for(let b of document.querySelectorAll('nav button')){let labels=navLabels[b.dataset.go],label=b.querySelector('small');if(labels&&label){let next=labels[preferences().ui==='en'?1:0];if(label.textContent!==next)label.textContent=next}}if(preferences().ui!=='en'||['admin','community','roster','submissions','issuereports'].includes(page))return;let walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){let el=n.parentElement;if(!el||el.closest('.verse,.tokens,textarea,[data-answer],[data-act^="pick:"],[data-act^="unpick:"],.history-row strong'))continue;if(!el.closest('button,label,option,h1,h2,h3,small,.muted,summary,.pill'))continue;let t=translateLabel(n.nodeValue);if(t!==n.nodeValue)n.nodeValue=t}for(let el of app.querySelectorAll('[placeholder]:not([data-answer])')){let old=el.getAttribute('placeholder'),t=translateLabel(old);if(old!==t)el.setAttribute('placeholder',t)}}

function preferences(){let p=db.preferences||{};return {ui:p.ui==='en'?'en':'ko',scripture:p.scripture==='en-US'?'en-US':'ko-KR',reference:['auto','ko','en','both'].includes(p.reference)?p.reference:'auto',font:['small','medium','large'].includes(p.font)?p.font:'medium',difficulty:['easy','medium','hard','expert'].includes(p.difficulty)?p.difficulty:'medium',count:[5,10,13,0].includes(p.count)?p.count:5,games:Array.isArray(p.games)&&p.games.some(g=>gameIds.includes(g))?gameIds.filter(g=>p.games.includes(g)):gameIds.slice()}}
const gameIds=['flash','reverse','choice','blank','order','hint','type'];
function reviewKey(x){return x.plan==='yes'&&x.lang==='en-US'?x.id+'-en':x.id}
function attemptLanguage(a){return a.language||'ko-KR'}
function matchesAttempt(a,x){return a.item===x.id&&(x.plan!=='yes'||attemptLanguage(a)===x.lang)}
function refLabel(id,language,setting=preferences().reference){let i=Number(id.slice(4));if(!officialIds.has(id))return '';return setting==='both'?refs[i]+' / '+englishRefs[i]:setting==='en'||(setting==='auto'&&language==='en-US')?englishRefs[i]:refs[i]}
function displayPrefs(){document.documentElement.dataset.verseSize=preferences().font;document.documentElement.lang=preferences().ui==='en'?'en':'ko'}
function publishedRows(){try{let v=JSON.parse(localStorage.getItem('yes-word-official-ko-v1'));return Array.isArray(v)?v:[]}catch{return []}}
function englishReady(rows=publishedRows()){return activeKeys.every(i=>rows.some(r=>r.item_key==='yes-'+i&&r.language==='en-US'&&typeof r.body==='string'&&r.body.trim()))}
function settingsPanel(){let p=preferences(),ready=englishReady();return '<section class="card stack"><h3>언어 설정 / Language</h3><label>앱 메뉴 언어 / App language</label><select id="pref-ui">'+options([['ko','한국어'],['en','English (beta)']],p.ui)+'</select><label>성경 본문 및 암송 언어 / Scripture language</label><select id="pref-scripture">'+options([['ko-KR','한국어 · 개역개정'],['en-US','English · ESV'+(ready?'':' (준비 중 / Coming soon)')]],p.scripture)+'</select><small>메뉴와 암송 언어를 독립적으로 선택합니다. 영어 본문은 관리자 공개 후 이용 가능합니다.</small><label>성경 주소 표시 / Reference language</label><select id="pref-reference">'+options([['auto','암송 언어에 맞추기'],['ko','한국어'],['en','English'],['both','한국어 + English']],p.reference)+'</select><h3>화면 / Appearance</h3><label>말씀 글자 크기</label><select id="pref-font">'+options([['small','작게'],['medium','보통'],['large','크게']],p.font)+'</select><label>테마</label><select id="pref-theme">'+options([['system','시스템'],['light','라이트'],['dark','다크']],db.theme)+'</select><h3>학습 / Practice</h3><label>하루 학습 목표</label><input id="pref-goal" type="number" min="1" max="100" value="'+db.goal+'"><label>기본 난이도</label><select id="pref-difficulty">'+options([['easy','Easy'],['medium','Medium'],['hard','Hard'],['expert','Expert']],p.difficulty)+'</select><label>랜덤 학습 문제 수</label><select id="pref-count">'+options([[5,'5문제'],[10,'10문제'],[13,'13문제'],[0,'선택 범위 전체']],p.count)+'</select><label>랜덤 학습에 포함할 게임</label>'+modes.filter(m=>m[0]!=='mixed').map(([id,t])=>'<label><input type="checkbox" data-pref-game="'+id+'" '+(p.games.includes(id)?'checked':'')+'> '+esc(t)+'</label>').join('')+'<h3>음성 / Audio</h3><label>재생 속도</label><select id="pref-rate">'+options([.5,.75,.9,1,1.25,1.5,2].map(v=>[v,v+'×']),db.audio.rate)+'</select><label>반복 횟수</label><select id="pref-repeat">'+options([1,2,3,5,10,0].map(v=>[v,v?v+'회':'무한']),db.audio.repeat)+'</select><label>반복 사이 휴식</label><select id="pref-gap">'+options([0,3,5,10,15,30].map(v=>[v,v+'초']),db.audio.gap)+'</select>'+btn('설정 저장','prefsapply','primary full')+'</section>'}
function savePreferences(){let old=preferences(),games=Array.from(app.querySelectorAll('[data-pref-game]:checked')).map(e=>e.dataset.prefGame);if(!games.length)return toast('랜덤 학습 게임을 하나 이상 선택하세요.');let language=$('#pref-scripture').value;if(language==='en-US'&&!englishReady())return toast('영어 본문은 관리자 공개 후 사용할 수 있습니다.');if($('#pref-difficulty').value==='expert'&&!games.some(g=>['order','hint','type'].includes(g)))return toast('Expert 난이도는 순서, 힌트, 전체 암송 중 하나가 필요합니다.');stopAllPlayback();db.preferences={...old,ui:$('#pref-ui').value,scripture:language,reference:$('#pref-reference').value,font:$('#pref-font').value,difficulty:$('#pref-difficulty').value,count:Number($('#pref-count').value),games};db.theme=$('#pref-theme').value;db.goal=Math.max(1,Math.min(100,Number($('#pref-goal').value)||3));db.audio.rate=Number($('#pref-rate').value);db.audio.repeat=Number($('#pref-repeat').value);db.audio.gap=Number($('#pref-gap').value);let rows=publishedRows();if(rows.length)applySharedTexts(rows);displayPrefs();save();theme();render();refreshSharedTexts(true);toast('설정 저장 완료')}
function personalization(){app.innerHTML=btn('← MY','goto:my','outline')+heading('Personalization','맞춤 설정')+settingsPanel()}
function languageQuick(){let p=preferences();if(page==='home'&&!db.preferences)return '<section class="card stack"><h3>나의 암송 언어 / Scripture language</h3><div class="row">'+btn('한국어','langfirst:ko-KR','primary grow')+btn('English · ESV','langfirst:en-US','outline grow',englishReady()?'':'disabled')+'</div><small>메뉴 언어와 암송 언어는 별도로 변경할 수 있습니다.</small>'+btn('세부 설정 / Settings','goto:personalization','outline full')+'</section>';return '<div class="row between" style="margin:8px 0 14px"><small>'+(p.scripture==='en-US'?'English · ESV':'한국어 · 개역개정')+'</small>'+btn('언어 및 맞춤 설정','goto:personalization','outline')+'</div>'}

const allFilled=()=>db.items.filter(x=>x.text.trim()); const filled=()=>allFilled().filter(inStudy); const item=id=>db.items.find(x=>x.id===id);const plan=id=>db.plans.find(x=>x.id===id);const due=()=>filled().filter(x=>!db.reviews[reviewKey(x)]||db.reviews[reviewKey(x)].next<=Date.now());
const mastery=x=>{let r=db.reviews[reviewKey(x)];return !x.text.trim()?0:!r?1:r.passes>=3&&r.tested?4:r.tested||r.self?3:2};const complete=x=>mastery(x)>=3;const pct=xs=>xs.length?Math.round(xs.filter(complete).length/xs.length*100):0;
const affiliations=['YES 청년부 · 새일꾼반','YES 청년부','개인 / 기타'];const validProfile=p=>p&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=40&&affiliations.includes(p.affiliation);let page='home',currentPlan='yes',editId=null,session=null,toastTimer;function toast(s){$('#toast').textContent=translateLabel(s);$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function theme(){document.documentElement.dataset.theme=db.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):db.theme}theme();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);$('#theme').onclick=()=>{db.theme=db.theme==='light'?'dark':db.theme==='dark'?'system':'light';save();theme();toast('테마: '+db.theme)};
const btn=(label,act,cls='',extra='')=>`<button class="${cls}" data-act="${act}" ${extra}>${label}</button>`;const bar=n=>`<div class="progress"><i style="width:${n}%"></i></div>`;const heading=(a,b)=>`<div class="eyebrow">YES WORD / ${esc(a)}</div><h1>${esc(b)}</h1>`;const options=(xs,selected)=>xs.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('');
function go(p,fromHistory=false){if(isGuest&&['admin','community','official','roster','submissions','issuereports'].includes(p))return toast('회원 전용 기능입니다. Google 계정으로 로그인해 주세요.');if(recording||recPending){toast('녹음을 먼저 종료해 주세요.');if(fromHistory)history.pushState({yesPage:page},'');return}if(p!==page){stopAllPlayback();if(!fromHistory)history.pushState({yesPage:p},'')}page=p;render();if(['home','plans','detail','study','listen'].includes(p))refreshSharedTexts();window.scrollTo(0,0)}
function render(){normalizeCurriculum(db);displayPrefs();if(!validProfile(db.profile))db.profile={...identity.profile};if(page==='welcome')page='home';document.body.classList.toggle('welcome-mode',page==='welcome');document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.go===({detail:'plans',edit:'plans',session:'study',result:'study',record:'listen',history:'my',personalization:'my',issue:'my',issuereports:'my',sharedview:'plans',admin:'my',community:'my',official:'listen',favorites:'study',bulkpage:'plans',roster:'my',submissions:'my'}[page]||page)));({home,plans,detail,edit,study,session:studySession,result,listen,record,my,install,welcome,profile:profilePage,admin:adminPage,community:communityPage,official:officialPage,roster:()=>cmGroup?rosterPage(cmGroup):communityPage(),submissions:()=>cmGroup?submissionsPage(cmGroup):communityPage(),favorites:favoritesPage,bulkpage:bulkPage,history:historyPage,personalization,issue:issuePage,issuereports:issueReports,sharedview:()=>sharedView(sharedViewId)}[page]||home)();localizeChrome()}
function brandMark(){return '<svg viewBox="0 0 80 80" aria-hidden="true"><path d="M40 32C31 26 22 25 13 28v28c10-3 19-2 27 4 8-6 17-7 27-4V28c-9-3-18-2-27 4zm0 0v28M40 11v12m-6-6h12" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
function profileForm(p){return '<form id="profileform" class="profile-form"><label for="profile-name">이름</label><input id="profile-name" name="name" autocomplete="given-name" maxlength="40" required placeholder="이름을 입력해 주세요" value="'+esc(p?.name||'')+'"><label for="profile-group">소속</label><select id="profile-group" name="affiliation">'+options(affiliations.map(x=>[x,x]),p?.affiliation||affiliations[0])+'</select><button class="primary full profile-submit" type="submit">'+(p?'변경 사항 저장':'말씀 여정 시작하기 →')+'</button></form>'}
function bindProfile(){ $('#profileform').onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target)),p={id:db.profile?.id||uid(),name:f.name.trim(),affiliation:f.affiliation,createdAt:db.profile?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(!validProfile(p))return toast('이름과 소속을 확인해 주세요.');if(isGuest){db.profile={...p,id:identity.id};save();go('home');return toast('프로필 저장 완료')}if(!window.YES_CLIENT)return toast('온라인 상태에서 프로필을 수정하세요.');let result=await window.YES_CLIENT.from('profiles').update({display_name:p.name,affiliation:p.affiliation}).eq('id',identity.id).select('id').single();if(result.error)return toast('프로필 저장 실패');p.id=identity.id;db.profile=p;try{localStorage.setItem('yes-word-device-profile-v1',JSON.stringify({...identity,profile:p}))}catch{}save();history.replaceState({yesPage:'home'},'');go('home',true);toast('프로필이 저장되었습니다.')} }
function welcome(){app.innerHTML='<div class="welcome-shell"><div class="welcome-brand"><div class="brand-mark">'+brandMark()+'<span>YES WORD</span></div><div class="welcome-kicker">YES MINISTRY · BIBLE MEMORY</div><h1>YES WORD<span>.</span></h1><p class="welcome-tagline">말씀을 마음에 새기다</p><div class="welcome-rule"></div><p class="welcome-caption">하루 한 걸음, 말씀과 함께.</p></div><section class="welcome-card"><h2>반가워요.</h2><p class="muted">나만의 말씀 암송 여정을 시작해 보세요.</p>'+profileForm(null)+'<p class="privacy-note">이름과 학습 기록은 현재 이 기기에만 저장됩니다. 계정 인증이나 관리자 공유는 아직 연결되지 않았습니다.</p></section><footer class="welcome-footer">His Word. Our Hearts. Everyday.<br><small>YES WORD · Korean Beta 0.3</small></footer></div>';bindProfile()}
function profilePage(){app.innerHTML=btn('← 나의 기록','goto:my','outline')+heading('Profile','나의 프로필')+'<section class="card"><div class="profile-avatar">'+esc(Array.from(db.profile.name)[0])+'</div>'+profileForm(db.profile)+'<p class="privacy-note">프로필 변경은 기존 암송 기록을 삭제하지 않습니다. '+(isGuest?'게스트 프로필은 이 기기에만 저장됩니다.':'변경 사항은 인증된 계정에 저장됩니다.')+'</p></section>';bindProfile()}
function home(){let xs=weeklyItems(),w=focusWeek(),focus=focusItems(),done=db.attempts.filter(a=>day(a.time)===day()).length;app.innerHTML='<div class="home-greeting"><div><div class="eyebrow">YES WORD / DAILY DEVOTION</div><h1>'+esc(db.profile.name)+(preferences().ui==='en'?', welcome.':' 님, 반가워요.')+'</h1><p class="muted">오늘도 말씀을 마음에 새겨요.</p></div><button class="profile-avatar" data-act="goto:profile" aria-label="프로필 수정">'+esc(Array.from(db.profile.name)[0])+'</button></div>'+languageQuick()+progressSelector()+`<section class="card stack yw-focus"><div class="row between"><h2 style="margin:0">이번 주 말씀</h2><span class="pill">${w.from===w.through?w.from:w.from+'~'+w.through}과</span></div>${focus.map(x=>`<div style="border-top:1px solid var(--line);padding-top:12px"><small>${x.lesson}과 · ${complete(x)?'암송 완료':'암송 연습'}</small><h3 style="margin:6px 0">${esc(x.ref)}</h3><div class="row">${btn('말씀 · 노트','sharedview:'+x.id,'outline grow')}${btn('암송','startitem:'+x.id,'outline',x.text?'':'disabled')}</div></div>`).join('')}${btn('이번 주 말씀 연습','weekpractice','primary full',focus.some(x=>x.text)?'':'disabled')}${btn('이번 주 말씀 듣기','weeklisten','outline full')}</section>${w.reading?`<section class="card stack"><small class="eyebrow">성경 읽기 · 다음 수업까지</small><div class="row between"><h3 style="margin:0">${esc(w.reading)}</h3>${btn(readingDone()?'✓ 완료':'읽기 완료','readingdone',readingDone()?'primary':'outline')}</div></section>`:''}<section class="card stack"><div class="row between"><h3 style="margin:0">누적 복습</h3><small>${xs.filter(complete).length} / ${xs.length}개</small></div>${bar(pct(xs))}${btn('누적 말씀 랜덤 학습','randomhome','primary full')}${btn('오늘 복습 ('+due().length+'개)','review','outline full')}${btn('전체 플랜 · 노트','openplan:yes','outline full')}</section>${futureWeeks(true)}<div class="grid"><div class="card"><small>오늘 학습</small><div class="metric">${done}/${db.goal}</div></div><div class="card"><small>나의 학습 말씀</small><div class="metric">${xs.length}개</div></div></div>`;}
function plans(){app.innerHTML=heading('Library','나의 플랜')+db.plans.map(p=>{let xs=db.items.filter(x=>x.plan===p.id&&inStudy(x));return `<section class="card"><div class="row between"><h3>${esc(p.title)}</h3><span class="pill">${xs.length}개</span></div>${bar(pct(xs))}<small>${xs.filter(complete).length}개 암송 완료</small><div class="row">${btn('열기','openplan:'+p.id,'primary grow')}${p.id!=='yes'?btn('이름 수정','renameplan:'+p.id,'outline'):''}</div></section>`}).join('')+`<section class="card"><label for="planname">새 플랜 이름</label><input id="planname" placeholder="예: 기도와 믿음">${btn('플랜 만들기','newplan','primary full')}</section>`}
function detail(){let p=plan(currentPlan);if(!p)return go('plans');let xs=db.items.filter(x=>x.plan===p.id&&inStudy(x));app.innerHTML=btn('← 플랜 목록','goto:plans','outline')+heading('Plan',p.title)+`<p class="muted">${xs.length}개 학습 중 · ${p.id==='yes'?'수업 진도와 관계없이 전체 말씀을 미리 볼 수 있어요.':'개인 본문을 직접 입력하세요.'}</p>${p.id==='yes'?weekPanel():''}${bar(pct(xs))}<div class="row">${btn('암송 시작','startplan:'+p.id,'primary grow')}${btn('연속 듣기','listenplan:'+p.id,'outline grow')}</div>`+xs.map(x=>`<section class="card"><div class="row between"><small>${x.lesson?x.lesson+'과':'개인 구절'}</small><span class="pill">${['입력 대기','학습 전','학습 중','암송 성공','장기 암송'][mastery(x)]}</span></div><h3>${esc(x.ref)}</h3>${x.text?`<p class="muted">${esc(x.text.slice(0,48))}${x.text.length>48?'…':''}</p>`:''}<div class="row">${p.id==='yes'?btn('말씀 보기','sharedview:'+x.id,'outline grow',x.text?'':'disabled'):btn(x.text?'본문 수정':'본문 입력','edit:'+x.id,'outline grow')}${btn('암송','startitem:'+x.id,'primary',x.text?'':'disabled')}${btn(x.favorite?'★ 저장됨':'☆ 추가','fav:'+x.id,'outline','aria-label="즐겨찾기"')}</div>${notePanel(x)}</section>`).join('')+(p.id==='yes'?futureWeeks():`<div class="row">${btn('+ 말씀 추가','newitem','primary grow')}${btn('일괄 입력','bulk','outline grow')}</div>`)}
function edit(){if(currentPlan==='yes'||item(editId)?.plan==='yes')return go('detail');let x=item(editId)||{ref:'',text:'',translation:'개역개정',lang:'ko-KR',notes:''};app.innerHTML=btn('← 플랜','goto:detail','outline')+heading('Scripture',editId?'말씀 편집':'말씀 추가')+`<form id="editform" class="card stack"><div><label>성경 주소 / 제목</label><input name="ref" value="${esc(x.ref)}" required></div><div class="grid"><div><label>번역본</label><input name="translation" value="${esc(x.translation)}"></div><div><label>언어</label><select name="lang">${options([['ko-KR','한국어'],['en-US','English']],x.lang)}</select></div></div><div><label>말씀 본문 (직접 입력)</label><textarea name="text" rows="7" required>${esc(x.text)}</textarea></div><div><label>개인 묵상 노트</label><textarea name="notes">${esc(x.notes)}</textarea></div><button class="primary">저장</button></form>`+(editId?btn('삭제 (48시간 복구 가능)','trash:'+editId,'outline full'):'');$('#editform').onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.text.trim()||!f.ref.trim())return toast('주소와 본문을 입력하세요.');if(editId){let old=item(editId);if(old.text!==f.text||old.ref!==f.ref||old.translation!==f.translation||old.lang!==f.lang){old.revisions=[...(old.revisions||[]),{text:old.text,ref:old.ref,version:old.version,time:Date.now()}];old.version++;delete db.reviews[old.id]}Object.assign(old,f)}else db.items.push({id:uid(),plan:currentPlan,lesson:null,version:1,favorite:false,...f});save();go('detail');toast('저장되었습니다.')}}
const initials='ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ';const initialHint=t=>Array.from(t,c=>{let n=c.charCodeAt(0)-44032;return n>=0&&n<11172?initials[Math.floor(n/588)]:/[a-z]/i.test(c)?'·':c}).join('');const wordHint=t=>/[가-힣]/.test(t)?initialHint(t):Array.from(t)[0]+'…';
const modes=[['flash','앞뒤 카드'],['reverse','역방향 카드'],['choice','빈칸 객관식'],['blank','빈칸 입력'],['order','순서 맞추기'],['hint','첫 글자 힌트'],['type','전체 암송'],['mixed','종합 시험']];
function study(){app.innerHTML=heading('Practice','암송 훈련')+`<section class="card stack"><label>학습 범위</label><select id="scope">${options([['weekly','이번 주 말씀 ('+scoped('weekly').length+'개)'],['all','학습 중인 전체 말씀 ('+filled().length+'개)'],['due','오늘 복습 ('+due().length+'개)'],['fav','즐겨찾기 ('+filled().filter(x=>x.favorite).length+'개)'],['wrong','오답 말씀 ('+wrongItems().length+'개)'],['selected','직접 선택'],...db.plans.map(p=>[p.id,p.title])],studyScope)}</select><div id="scope-guide" class="muted"></div>${btn('즐겨찾기 관리','goto:favorites','outline full')}<label>난이도</label><select id="difficulty">${options([['easy','Easy · 20%'],['medium','Medium · 40%'],['hard','Hard · 70%'],['expert','Expert · 전체 암송']],preferences().difficulty)}</select><label><input type="checkbox" id="shuffle"> 무작위 순서</label></section><section class="card stack"><h3>랜덤 학습</h3><p class="muted">학습 중인 말씀을 여러 게임으로 반복 연습합니다.</p><label for="random-count">문제 수</label><select id="random-count">${options([[5,'5문제'],[10,'10문제'],[13,'13문제'],[0,'선택 범위 전체']],preferences().count)}</select>${btn('랜덤 학습 시작','randomstudy','primary full')}</section><h2>게임별 학습</h2><div class="grid">${modes.map(([id,t],i)=>`<button class="card" data-act="mode:${id}"><span class="eyebrow">0${i+1}</span><br><b>${t}</b></button>`).join('')}</div>`;$('#scope').onchange=e=>{studyScope=e.target.value;studyScopeUI()};studyScopeUI()}
const shuffle=xs=>{let a=[...xs];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};const scoped=s=>s==='weekly'?focusItems().filter(x=>x.text.trim()):s==='wrong'?wrongItems():s==='selected'?filled().filter(x=>selectedStudy.has(x.id)):s==='all'?filled():s==='due'?due():s==='fav'?filled().filter(x=>x.favorite):s.startsWith('item:')?filled().filter(x=>x.id===s.slice(5)):filled().filter(x=>x.plan===s);
const norm=s=>String(s).normalize('NFC').toLowerCase().replace(/[\p{P}\p{Z}\s]/gu,'');function score(a,b){a=Array.from(norm(a));b=Array.from(norm(b));let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let cur=[i];for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=cur}return Math.round(100*(1-prev[b.length]/Math.max(a.length,b.length,1)))}
function randomRound(xs,difficulty=preferences().difficulty,count=preferences().count){let unique=Array.from(new Map(xs.filter(x=>x.text.trim()).map(x=>[x.id,x])).values());if(!unique.length)return toast('학습할 말씀이 없습니다.');let target=count||unique.length,selected=[];while(selected.length<target){let round=shuffle(unique);if(round.length>1&&selected.length&&round[0].id===selected[selected.length-1].id)[round[0],round[1]]=[round[1],round[0]];selected.push(...round.slice(0,target-selected.length))}let allowed=preferences().games,pool=(difficulty==='expert'?['order','hint','type']:gameIds).filter(g=>allowed.includes(g));if(!pool.length)return toast('현재 난이도에 사용할 랜덤 게임을 설정해 주세요.');let schedule=[],bag=[];for(let i=0;i<selected.length;i++){if(!bag.length){bag=shuffle(pool);if(bag.length>1&&schedule.length&&bag[0]===schedule[schedule.length-1]){[bag[0],bag[1]]=[bag[1],bag[0]]}}schedule.push(bag.shift())}session={ids:selected.map(x=>x.id),mode:'random',difficulty,index:0,results:[],q:null,schedule,scope:studyScope};go('session')}
function start(xs,mode='flash',difficulty='medium',random=false){if(!xs.length)return toast('먼저 말씀 본문을 입력해 주세요.');session={ids:(random?shuffle(xs):xs).map(x=>x.id),mode,difficulty,index:0,results:[],q:null};go('session')}
function question(x){let mode=session.mode==='random'?session.schedule[session.index]:session.mode==='mixed'?shuffle(['blank','order','type','hint'])[0]:session.mode;let tokens=x.text.trim().split(/\s+/);let ratio={easy:.2,medium:.4,hard:.7,expert:1}[session.difficulty];if(session.difficulty==='expert'&&['blank','choice'].includes(mode))mode='type';let hidden=shuffle(tokens.map((_,i)=>i)).slice(0,Math.max(1,Math.round(tokens.length*ratio)));let q={mode,tokens,hidden,flip:false,selected:[],answers:{},typed:'',hint:false,graded:false,score:0,order:shuffle(tokens.map((_,i)=>i))};q.choices={};for(let i of hidden){let other=[...new Set([...tokens,...filled().filter(v=>v.lang===x.lang).flatMap(v=>v.text.split(/\s+/))])].filter(t=>norm(t)&&norm(t)!==norm(tokens[i]));let seen=new Set();other=other.filter(t=>!seen.has(norm(t))&&seen.add(norm(t)));q.choices[i]=shuffle([tokens[i],...shuffle(other).slice(0,3)])}return q}
function studySession(){if(!session||session.index>=session.ids.length)return go('result');let x=item(session.ids[session.index]);if(!x)return nextQuestion();let q=session.q||(session.q=question(x));let flash=['flash','reverse'].includes(q.mode);let body='';if(flash){let front=q.mode==='flash'?x.ref:x.text,back=q.mode==='flash'?x.text:x.ref;body=`<button class="flip" data-act="flip"><small>${q.flip?'정답':'말씀을 떠올려 보세요'}</small><span class="verse">${esc(q.flip?back:front)}</span><small>탭하여 뒤집기 ↻</small></button>${q.flip?`<div class="grid">${btn('다시 연습','rate:again','outline')}${btn('어려워요','rate:hard','outline')}${btn('외웠어요','rate:good','primary')}${btn('완벽해요','rate:easy','primary')}</div>`:''}`}else if(q.mode==='order'){body=`<div class="card tokens" id="answerOrder">${q.selected.length?q.selected.map(i=>btn(esc(q.tokens[i]),'unpick:'+i,'outline',q.graded?'disabled':'')).join(''):'<small>아래 단어를 순서대로 선택하세요.</small>'}</div><div class="tokens">${q.order.filter(i=>!q.selected.includes(i)).map(i=>btn(esc(q.tokens[i]),'pick:'+i,'',q.graded?'disabled':'')).join('')}</div>`}else if(['blank','choice'].includes(q.mode)){body=`<div class="card verse">${q.tokens.map((t,i)=>!q.hidden.includes(i)?esc(t):q.mode==='choice'&&q.choices[i].length>1?`<select class="blank" data-answer="${i}" ${q.graded?'disabled':''}>${options([['','선택'],...q.choices[i].map(a=>[a,a])],q.answers[i]||'')}</select>`:`<input class="blank" data-answer="${i}" value="${esc(q.answers[i]||'')}" placeholder="${q.hint?esc(wordHint(t)):'___'}" ${q.graded?'disabled':''}>`).join(' ')}</div>`}else{body=(q.mode==='hint'?`<div class="card verse">${esc(q.tokens.map(wordHint).join(' '))}</div>`:'')+`<textarea id="recall" rows="7" placeholder="말씀을 기억하며 입력하세요" ${q.graded?'disabled':''}>${esc(q.typed)}</textarea>`}if(!flash){body+=q.graded?`<section class="card"><div class="metric ${q.score>=90?'good':'error'}">${q.score}점</div><small>${q.hint?'힌트 사용 · 암송 성공 판정 제외':''}</small><h3>원문</h3><p class="verse">${esc(x.text)}</p></section>${btn('다음 →','next','primary full')}`:`<div class="row">${btn('힌트 보기','hintshow','outline grow')}${btn('채점하기','grade','primary grow')}</div>${q.hint?`<div class="hint-panel"><small>${x.lang==='en-US'?'First letter hints':'초성 힌트'}</small><p>${esc(q.tokens.map((t,i)=>['blank','choice'].includes(q.mode)&&!q.hidden.includes(i)?t:wordHint(t)).join(' '))}</p></div>`:''}`}app.innerHTML=`<div class="row between">${btn('종료','endstudy','outline')}<small>${session.mode==='random'?'랜덤 학습 · ':''}${session.index+1} / ${session.ids.length}</small></div>${bar(session.index/session.ids.length*100)}<h2>${esc(q.mode==='reverse'?'성경 주소를 떠올려 보세요':x.ref)}</h2><p class="muted">${modes.find(m=>m[0]===q.mode)?.[1]}</p>${body}`;app.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>q.answers[el.dataset.answer]=el.value);if($('#recall'))$('#recall').oninput=e=>q.typed=e.target.value}
function logAttempt(x,sc,rating,kind,hint){let now=Date.now(),r=db.reviews[reviewKey(x)]||{stage:-1,passes:0,tested:false,self:false,lastPass:0,next:0};let wasDue=r.next<=now;let pass=rating==='good'||rating==='easy';if(pass){r.stage=Math.min(4,r.stage+1);if(kind==='test'&&!hint&&sc>=90){if(r.tested&&wasDue&&day(r.lastPass)!==day(now))r.passes++;r.tested=true;r.lastPass=now}else if(kind==='self')r.self=true}else if(rating==='again'){r.stage=-1;r.passes=0;r.tested=false;r.self=false}r.next=now+86400000*[1,3,7,14,30][Math.max(0,r.stage)];db.reviews[reviewKey(x)]=r;let a={id:uid(),item:x.id,language:x.lang,reference:x.ref,time:now,mode:session?.q?.mode||'voice',score:sc,rating,kind,hint,version:x.version};db.attempts.push(a);session?.results.push(a);save()}
function grade(){let q=session.q,x=item(session.ids[session.index]);if(q.graded)return;let sc;if(q.mode==='order')sc=score(q.selected.map(i=>q.tokens[i]).join(' '),x.text);else if(['blank','choice'].includes(q.mode))sc=Math.round(q.hidden.filter(i=>norm(q.answers[i]||'')===norm(q.tokens[i])).length/q.hidden.length*100);else sc=score(q.typed,x.text);q.score=sc;q.graded=true;let full=['type','order'].includes(q.mode)||(['blank','choice'].includes(q.mode)&&q.hidden.length===q.tokens.length);let kind=full?'test':'practice';logAttempt(x,sc,sc>=90&&!q.hint?'good':sc>=60?'hard':'again',kind,q.hint);render()}
function nextQuestion(){session.index++;session.q=null;go(session.index>=session.ids.length?'result':'session')}
function result(){let rs=session?.results||[],scores=rs.filter(r=>r.score!==null);app.innerHTML=heading('Complete',session?.mode==='random'?'랜덤 학습을 마쳤어요!':'학습을 마쳤어요!')+`<section class="card hero center"><h2>${rs.length}개 학습</h2><div class="metric">${scores.length?Math.round(scores.reduce((a,b)=>a+b.score,0)/scores.length)+'점':'자기 평가'}</div><p>오늘도 말씀을 마음에 새겼습니다.</p></section>${session?.mode==='random'?btn('새로운 랜덤 학습','randomagain','primary full'):''}${btn('다시 연습','goto:study',session?.mode==='random'?'outline full':'primary full')}${btn('홈으로','goto:home','outline full')}`}
let audioRun=0,audioState={active:false,ref:'',index:0,total:0,paused:false},audioTimer=null,mainAudio=null,mainAudioUrl=null,mainAudioCancel=null,mainTracks=new Map();function voices(){return window.speechSynthesis?.getVoices()||[]}function listen(){app.innerHTML=heading('Listen','말씀 듣기')+'<div id="official-entry">'+(officialEnabled?btn('공식 말씀 음성','goto:official','outline full'):'')+'</div>'+`<div class="art"><span>✧</span><b>YES WORD</b><small style="color:#e1e8dd">His Word. Our Hearts. Everyday.</small></div><section class="card"><div id="nowplaying"><h3>${esc(audioState.ref||'말씀을 선택하세요')}</h3><small>${audioState.active?(audioState.paused?'일시정지':'재생 중')+' · '+(audioState.index+1)+' / '+audioState.total:'재생 대기'}</small></div><div class="row" style="margin-top:12px">${btn('▶ 시작','play','primary grow')}${btn('일시정지 / 계속','pause','outline')}${btn('■','stop','outline')}</div><label>재생 범위</label><select id="audioScope">${options([['weekly','이번 주 말씀'],['all','학습 중인 모든 말씀'],['official-all','전체 공식 말씀 (13과)'],['fav','즐겨찾기'],['due','복습할 말씀'],...db.plans.map(p=>[p.id,p.title]),...allFilled().map(x=>['item:'+x.id,(x.plan==='yes'&&!inStudy(x)?'미리 듣기 · ':'')+x.ref])],audioState.scope||'all')}</select><p class="muted" id="audio-source-info">공식 녹음만 재생됩니다. AI가 읽어주는 음성은 준비 중입니다.</p><div class="grid"><div><label>속도</label><select id="rate">${options([.5,.75,.9,1,1.25,1.5,2].map(v=>[v,v+'×']),db.audio.rate)}</select></div><div><label>반복 횟수</label><select id="repeat">${options([1,2,3,5,10,0].map(v=>[v,v?v+'회':'무한']),db.audio.repeat)}</select></div><div><label>반복 사이 휴식</label><select id="gap">${options([0,3,5,10,15,30].map(v=>[v,v+'초']),db.audio.gap)}</select></div><div><label>종료 타이머</label><select id="timer">${options([0,5,10,15,30].map(v=>[v,v?v+'분':'사용 안 함']),db.audio.timer)}</select></div></div><label><input type="checkbox" id="audioshuffle" ${db.audio.shuffle?'checked':''}> 무작위 재생</label><p class="muted">따라 읽기: 휴식 시간을 설정하고 반복 재생 중 직접 말씀을 따라 읽으세요. 화면 잠금 상태 재생은 기기마다 다릅니다.</p></section>${btn('내 목소리 녹음 및 듣기','goto:record','primary full')}`;['rate','repeat','gap','timer','audioshuffle'].forEach(id=>$('#'+id).onchange=e=>{let key={readref:'reference',audioshuffle:'shuffle'}[id]||id;db.audio[key]=e.target.type==='checkbox'?e.target.checked:Number(e.target.value);save()});refreshVisibleAudio()}
function audioUI(){if($('#nowplaying'))$('#nowplaying').innerHTML=`<h3>${esc(audioState.ref||'말씀을 선택하세요')}</h3><small>${audioState.active?(audioState.paused?'일시정지':'재생 중')+' · '+(audioState.index+1)+' / '+audioState.total:'재생 종료'}</small>${audioState.source?'<p class="muted">'+esc(audioState.source)+'</p>':''}`}
function stopAllPlayback(){releaseVerseAudio();communityStop();stopAudio();document.querySelectorAll('audio').forEach(a=>{a.pause();a.currentTime=0});recUrls.forEach(URL.revokeObjectURL);recUrls=[]}function stopAudio(){audioRun++;if(mainAudioCancel){let f=mainAudioCancel;mainAudioCancel=null;f(false)}if(mainAudio){mainAudio.pause();mainAudio.removeAttribute('src');mainAudio=null}if(mainAudioUrl){URL.revokeObjectURL(mainAudioUrl);mainAudioUrl=null}window.speechSynthesis?.cancel();clearTimeout(audioTimer);audioState.active=false;audioState.paused=false;audioUI()}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));function speak(text,lang,run){return new Promise(resolve=>{if(run!==audioRun)return resolve(false);let u=new SpeechSynthesisUtterance(text);u.lang=lang;u.rate=db.audio.rate;let compatible=voices().filter(v=>v.lang.toLowerCase().startsWith(lang.slice(0,2).toLowerCase()));let v=compatible.find(v=>/natural|neural|premium/i.test(v.name))||compatible.find(v=>/google/i.test(v.name))||compatible.find(v=>v.default)||compatible[0];if(v)u.voice=v;let started=Date.now();u.onend=()=>{if(run===audioRun){db.listening+=Math.max(0,Math.round((Date.now()-started)/1000));save()}resolve(true)};u.onerror=()=>resolve(false);speechSynthesis.speak(u)})}
async function loadMainTracks(){
 let out=new Map();await refreshOfficialSetting();if(!officialEnabled)return out;
 let rows;if(isGuest&&navigator.onLine){rows=await guestOfficialFetch('rest/v1/official_audio?select=id,item_key,language,title,object_path,created_at&published=eq.true&order=created_at.desc')}else if(window.YES_CLIENT&&navigator.onLine){rows=must(await onlineCommunity().from('official_audio').select('id,item_key,language,title,object_path,created_at').eq('published',true).order('created_at',{ascending:false}))}else{rows=(await officialOp('readonly',s=>s.getAll()).catch(()=>[])).map(x=>x.meta).filter(Boolean).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))}
 for(let a of rows){let key=a.item_key+'|'+a.language;if(!out.has(key))out.set(key,a)}return out
}
async function playMainRecording(track,run){let blob=await officialBlob(track);if(run!==audioRun)return false;if(!blob||!blob.size)throw Error('등록된 음성 파일이 비어 있습니다.');mainAudioUrl=URL.createObjectURL(blob);let player=new Audio(mainAudioUrl);mainAudio=player;player.playbackRate=db.audio.rate;let started=Date.now();try{while(audioState.paused&&run===audioRun)await sleep(100);if(run!==audioRun)return false;let ok=await new Promise((resolve,reject)=>{mainAudioCancel=resolve;player.onended=()=>resolve(true);player.onerror=()=>reject(Error('등록 음성 파일을 재생할 수 없습니다.'));player.play().catch(reject)});if(ok&&run===audioRun){db.listening+=Math.max(0,Math.round(player.duration/Math.max(.5,player.playbackRate)||((Date.now()-started)/1000)));save()}return ok}finally{if(mainAudio===player){mainAudioCancel=null;player.pause();player.removeAttribute('src');mainAudio=null;if(mainAudioUrl){URL.revokeObjectURL(mainAudioUrl);mainAudioUrl=null}}}}
function audioScoped(scope){if(scope==='official-all')return allFilled().filter(x=>x.plan==='yes');if(scope.startsWith('item:'))return allFilled().filter(x=>x.id===scope.slice(5));return scoped(scope)}
async function playAudio(scope){let xs=audioScoped(scope);if(!xs.length)return toast('먼저 말씀을 입력해 주세요.');stopAudio();let run=audioRun;audioState={active:true,ref:xs[0].ref,index:0,total:xs.length,scope,paused:false,source:'음성 확인 중…'};audioUI();try{mainTracks=await loadMainTracks();if(run!==audioRun)return;xs=xs.filter(x=>x.plan==='yes'&&mainTracks.has(x.id+'|'+x.lang));audioState.total=xs.length;if(!xs.length){stopAudio();audioState.source='공식 음성 준비 중 · AI가 읽어주는 음성 준비 중';audioUI();return toast('음성 준비 중입니다.')}if(db.audio.shuffle)xs=shuffle(xs);if(db.audio.timer)audioTimer=setTimeout(stopAudio,db.audio.timer*60000);for(let i=0;i<xs.length&&run===audioRun;i++){let x=xs[i],track=x.plan==='yes'?mainTracks.get(x.id+'|'+x.lang):null;audioState.ref=x.ref;audioState.index=i;audioState.source='관리자 등록 녹음';audioUI();let n=db.audio.repeat||Infinity;for(let j=0;j<n&&run===audioRun;j++){while(audioState.paused&&run===audioRun)await sleep(100);if(run!==audioRun)return;let ok=await playMainRecording(track,run);if(!ok){if(run===audioRun)throw Error('음성 재생이 중단되었습니다.');return}if(j<n-1||i<xs.length-1)for(let t=0;t<db.audio.gap*10&&run===audioRun;){await sleep(100);if(!audioState.paused)t++}}}if(run===audioRun)stopAudio()}catch(e){if(run===audioRun){stopAudio();audioState.source='재생 실패 · '+(e.message||'다시 시작해 주세요.');audioUI();toast(audioState.source)}}}

let recDB;function audioDB(){return recDB||(recDB=new Promise((resolve,reject)=>{let req=indexedDB.open('yes-word-recordings:'+identity.id,1);req.onupgradeneeded=()=>req.result.createObjectStore('recordings',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}))}async function recOp(mode,fn){let d=await audioDB();return new Promise((resolve,reject)=>{let tx=d.transaction('recordings',mode),r=fn(tx.objectStore('recordings'));tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
let recording=null,recStream=null,recStart=0,recInterval=null,recPending=false,recUrls=[];async function record(){stopAllPlayback();recUrls.forEach(URL.revokeObjectURL);recUrls=[];app.innerHTML=btn('← 듣기','goto:listen','outline')+heading('Recite','내 목소리로 암송')+`<section class="card center"><label>암송할 말씀</label><select id="recItem">${options(filled().map(x=>[x.id,x.ref]),filled()[0]?.id)}</select><p class="muted">본문을 보지 않고 암송해 보세요.</p><div class="metric" id="recTime">00:00</div><div class="row" style="justify-content:center;margin:16px 0">${btn('● 녹음 시작','recstart','primary')}${btn('■ 종료','recstop','outline','disabled')}</div><p class="muted">최대 5분 · 이 기기에만 저장</p>${btn('원문 듣기','reccompare','outline full')}</section><h2>녹음 기록</h2><div id="recList">불러오는 중…</div>`;try{let rows=await recOp('readonly',s=>s.getAll());if(page!=='record'||!$('#recList'))return;$('#recList').innerHTML=rows.length?rows.sort((a,b)=>b.time-a.time).map(r=>{let url=URL.createObjectURL(r.blob);recUrls.push(url);return `<section class="card"><h3>${esc(r.name)}</h3><small>${esc(new Date(r.time).toLocaleString('ko-KR'))} · ${Math.round(r.duration/1000)}초</small><div class="record-play"><audio preload="metadata" src="${url}"></audio><button class="outline" data-act="recordplay:${r.id}" aria-label="녹음 재생 또는 일시정지">▶ 듣기</button><span class="record-time">0:00</span></div><div class="row">${btn('이름 수정','recrename:'+r.id,'outline grow')}${btn('다운로드','recdownload:'+r.id,'outline')}${btn('삭제','recdelete:'+r.id,'outline')}</div></section>`}).join(''):'<p class="muted">아직 녹음이 없습니다.</p>'}catch{if($('#recList'))$('#recList').textContent='녹음 저장소에 접근할 수 없습니다.'}}
async function recStartFn(){if(recording||recPending)return;let x=item($('#recItem')?.value);if(!x)return toast('먼저 본문을 입력하세요.');if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('HTTPS 환경의 지원 브라우저에서 녹음할 수 있습니다.');recPending=true;try{stopAudio();recStream=await navigator.mediaDevices.getUserMedia({audio:true});if(page!=='record'){recStream.getTracks().forEach(t=>t.stop());return}let chunks=[],r=new MediaRecorder(recStream);recording=r;recStart=Date.now();r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.onstop=async()=>{clearInterval(recInterval);recStream?.getTracks().forEach(t=>t.stop());recording=null;let blob=new Blob(chunks,{type:r.mimeType||chunks[0]?.type||'audio/webm'});try{await recOp('readwrite',s=>s.put({id:uid(),item:x.id,name:x.ref,blob,time:Date.now(),duration:Date.now()-recStart}));toast('녹음 저장 완료')}catch{toast('녹음 저장에 실패했습니다.')}if(page==='record')record()};r.onerror=()=>{recStream?.getTracks().forEach(t=>t.stop());clearInterval(recInterval);recording=null;toast('녹음 오류');if(page==='record')record()};r.start();$('[data-act=recstart]').disabled=true;$('[data-act=recstop]').disabled=false;recInterval=setInterval(()=>{let sec=Math.floor((Date.now()-recStart)/1000);if($('#recTime'))$('#recTime').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec>=300&&r.state==='recording')r.stop()},250)}catch{recStream?.getTracks().forEach(t=>t.stop());recording=null;toast('마이크 권한 또는 기기를 확인하세요.')}finally{recPending=false}}
function streak(){let days=new Set(db.attempts.map(a=>day(a.time)));let d=new Date(),n=0;if(!days.has(day(d)))d.setDate(d.getDate()-1);while(days.has(day(d))){n++;d.setDate(d.getDate()-1)}return n}
function my(){adminCheck().then(()=>{if(page==='my'&&$('#community-links'))$('#community-links').innerHTML=communityNav()});let count=filled().filter(complete).length,st=streak(),scores=db.attempts.filter(a=>a.score!==null);db.trash=db.trash.filter(x=>Date.now()-x.deleted<172800000);save();app.innerHTML=heading('My journey','나의 기록')+`<section class="card row between account-overview"><div><h3>${esc(db.profile.name)}</h3><small>${esc(db.profile.affiliation)}</small></div>${btn('프로필','goto:profile','outline')}</section><section class="card stack" id="community-links">${communityNav()}</section><div class="grid"><div class="card"><small>연속 학습</small><div class="metric">${st}일</div></div><div class="card"><small>암송 완료</small><div class="metric">${count}개</div></div><div class="card"><small>전체 학습</small><div class="metric">${db.attempts.length}회</div></div><div class="card"><small>말씀 듣기</small><div class="metric">${Math.floor(db.listening/60)}분</div></div></div>${historySummary()}<section class="card stack"><h3>설정</h3>${btn('언어 및 맞춤 설정','goto:personalization','primary full')}<p class="muted">${esc(identity.email||'')}</p>${btn(isGuest?'게스트 모드 종료':'로그아웃','signout','outline')}${!isGuest?btn('이전 기기 기록 가져오기','legacyimport','outline')+guestImportButton():''}${btn("나의 프로필 수정","goto:profile","outline")}${btn("앱 설치 및 오프라인 안내","goto:install","outline")}<label>하루 학습 목표</label><input type="number" min="1" max="100" id="goal" value="${db.goal}"><label>테마</label><select id="themeselect">${options([['system','시스템'],['light','라이트'],['dark','다크']],db.theme)}</select>${btn('즐겨찾기 암송','favoriteStudy','outline')}${btn('개인 데이터 JSON 백업','backup','outline')}${btn('백업 복원','restore','outline')}<input type="file" id="restorefile" accept="application/json" hidden><small>녹음 파일은 별도로 다운로드하세요. 데이터는 이 기기의 브라우저에 저장됩니다. ${isGuest?'게스트는 서버에 기록을 저장하지 않습니다.':'학습 기록은 계정별로 이 기기에 저장됩니다. 클라우드 동기화에서 선택적으로 백업할 수 있습니다.'}</small></section>${syncPanel()}<h2>휴지통</h2>${db.trash.map(x=>`<div class="card row between"><span>${esc(x.ref)}</span>${btn('복구','recover:'+x.id,'outline')}</div>`).join('')||'<p class="muted">삭제된 항목이 없습니다.</p>'}<p class="muted">YES WORD v0.32 · 언어 및 맞춤 설정</p>`;$('#goal').onchange=e=>{db.goal=Math.max(1,Math.min(100,Number(e.target.value)||3));save()};$('#themeselect').onchange=e=>{db.theme=e.target.value;save();theme()};$('#restorefile').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;let o=JSON.parse(await f.text());if(o.schema!==1||!Array.isArray(o.items)||!Array.isArray(o.plans)||!Array.isArray(o.attempts)||!o.reviews||!o.audio||!Array.isArray(o.trash)||!o.items.every(x=>typeof x.id==='string'&&typeof x.ref==='string'&&typeof x.text==='string'&&typeof x.plan==='string')||!o.plans.every(p=>typeof p.id==='string'&&typeof p.title==='string'))throw Error();if(confirm('현재 개인 학습 데이터를 백업 파일로 교체할까요?')){db={...initial(),...o,profile:db.profile};save();theme();render();toast('복원 완료')}}catch{toast('유효한 YES WORD 백업 파일이 아닙니다.')}}}
function install(){app.innerHTML=btn('← 나의 기록','goto:my','outline')+heading('Install','앱 설치 및 오프라인')+'<section class="card"><h3>iPhone / iPad</h3><p>Safari에서 YES WORD 주소 열기 → 공유 → 홈 화면에 추가 → 추가.</p><h3>Android</h3><p>Chrome 메뉴 ⋮ → 앱 설치 또는 홈 화면에 추가.</p></section><section class="card"><h3>오프라인 사용</h3><p>온라인 상태에서 앱을 한 번 열고 캐시 준비를 확인한 후 비행기 모드에서 다시 실행하세요. 말씀 입력, 암송, 로컬 녹음은 기기에 저장됩니다. 자동 읽기 음성은 기기별로 인터넷이 필요할 수 있습니다.</p><p id="offline-status">확인 중…</p></section>';let el=$('#offline-status');if(!navigator.serviceWorker){el.textContent='이 브라우저는 오프라인 설치를 지원하지 않습니다.';return}navigator.serviceWorker.getRegistration().then(async r=>{let c=await caches.open('yes-word-v32');let checks=await Promise.all(['./','./index.html','./style.css?v=32','./app.js?v=32','./gate.js?v=32','./manifest.webmanifest?v=32','./icon-192.png?v=3','./icon-512.png?v=3'].map(x=>c.match(new URL(x,location.href).href)));if(el.isConnected)el.textContent=r?.active&&checks.every(Boolean)?'오프라인 캐시 준비 완료 · 비행기 모드에서 확인하세요.':'아직 캐시 준비 중입니다. 온라인 상태에서 새로고침해 주세요.'}).catch(()=>{if(el.isConnected)el.textContent='오프라인 상태를 확인할 수 없습니다.'})}
function download(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function action(a){let [k,id]=a.split(':');if(isGuest&&(k.startsWith('official')||k.startsWith('cm')||k.startsWith('cloud')||k==='legacyimport'))return toast('회원 전용 기능입니다.');if(k.startsWith('official')&&!['officialsetting','officialtextsimport'].includes(k))return officialAction(k,id);if(k.startsWith('cm'))return communityAction(k,id);switch(k){case'weekpractice':studyScope='weekly';return randomRound(scoped('weekly'),preferences().difficulty,preferences().count);case'weeklisten':audioState.scope='weekly';go('listen');return playAudio('weekly');case'readingdone':return toggleReading();case'weekadminsave':return saveWeeklyConfig();case'weekadminschedule':return saveWeeklyConfig(true);case'weeknext':return selectStudyWeek(String(personalWeek()+1));case'weekset':return selectStudyWeek($('#week-select').value);case'randomhome':studyScope='yes';return randomRound(scoped('yes'));case'randomstudy':studyScope=$('#scope').value;return randomRound(scoped(studyScope),$('#difficulty').value,Number($('#random-count').value));case'randomagain':{let previous=session;studyScope=previous.scope||'yes';return randomRound(scoped(studyScope),previous.difficulty,previous.ids.length)}case'langfirst':if(id==='en-US'&&!englishReady())return toast('English · 준비 중');db.preferences={...preferences(),scripture:id==='en-US'?'en-US':'ko-KR'};{let rows=publishedRows();if(rows.length)applySharedTexts(rows)}save();return render();case'prefsapply':return savePreferences();case'historylang':historyLanguage=id;historyLimit=30;return historyPage();case'historyrange':historyRange=id;historyLimit=30;return historyPage();case'historymore':historyLimit+=30;return historyPage();case'officialsetting':return toggleOfficialSetting();case'favfilter':favFilter=id;return favoritesPage();case'favtrain':if(!scoped('fav').length)return toast('본문이 등록된 말씀을 즐겨찾기에 추가하세요.');studyScope='fav';return go('study');case'cloudsync':return syncCloud();case'cloudpull':return syncCloud('pull');case'cloudpush':return syncCloud('push');case'cloudtoggle':{if(!syncMeta.enabled&&syncMeta.revision===null)return toast('먼저 지금 동기화로 초기 백업을 완료하세요.');persistSync({...syncMeta,enabled:!syncMeta.enabled});syncMessage=syncMeta.enabled?'자동 백업이 켜졌습니다.':'자동 백업이 꺼졌습니다.';if(!syncMeta.enabled)clearTimeout(syncTimer);render();return}case'cloudconflictbackup':return download(new Blob([localStorage.getItem(conflictKey)],{type:'application/json'}),'yes-word-conflict-backup.json');case'guestlogin':if(recording||recPending)return toast('녹음을 먼저 종료하세요.');stopAllPlayback();save();localStorage.removeItem('yes-word-guest-active');location.href='./account.html?v=32';return;case'guestimport':return importGuest();case'sharedview':return sharedView(id);case'officialtextsimport':return importOfficialTexts();case'signout':{if(isGuest){if(recording||recPending)return toast('녹음을 먼저 종료하세요.');stopAllPlayback();save();localStorage.removeItem('yes-word-guest-active');location.href='./account.html?v=32';return}if(syncBusy)return toast('동기화 완료 후 로그아웃하세요.');clearTimeout(syncTimer);if(recording||recPending)return toast('녹음을 먼저 종료하세요.');stopAllPlayback();if(window.YES_CLIENT){let r=await window.YES_CLIENT.auth.signOut({scope:'local'});if(r.error)return toast('로그아웃 실패. 다시 시도하세요.')}localStorage.removeItem('yes-word-auth-v1');localStorage.removeItem('yes-word-device-profile-v1');location.replace('./account.html?v=32');return}case'legacyimport':{if(localStorage.getItem('yes-word-legacy-claimed'))return toast('이전 기록은 이미 다른 계정 또는 현재 계정에 이전되었습니다.');let raw=localStorage.getItem('yes-word-v1');if(!raw)return toast('이전 기록이 없습니다.');let old;try{old=JSON.parse(raw);if(old.schema!==1||!Array.isArray(old.items)||!Array.isArray(old.plans)||!Array.isArray(old.attempts))throw Error()}catch{return toast('이전 데이터 형식을 확인하세요.')}if(db.attempts.length||db.items.some(x=>x.text.trim())||db.plans.length>1)return toast('현재 계정에 학습 데이터가 있습니다. 덮어쓰기를 방지하기 위해 이전할 수 없습니다.');if(!confirm('이 기기의 이전 기록 '+old.items.filter(x=>x.text?.trim()).length+'개와 학습 내역 '+old.attempts.length+'건이 본인의 것인지 확인하세요. 현재 계정에 복사할까요?'))return;let p=db.profile;let next={...initial(),...old,profile:p};try{localStorage.setItem(storageKey,JSON.stringify(next));localStorage.setItem('yes-word-legacy-claimed',identity.id)}catch{return toast('기록 이전 저장 실패')}db=next;save();theme();render();toast('기존 말씀 및 학습 기록 복사 완료. 녹음은 별도 보존됩니다.');return}case'goto':return go(id);case'openplan':currentPlan=id;return go('detail');case'newplan':{let t=$('#planname').value.trim();if(!t)return toast('플랜 이름을 입력하세요.');db.plans.push({id:uid(),title:t});save();return render()}case'renameplan':{let p=plan(id),t=prompt('플랜 이름',p.title);if(t?.trim()){p.title=t.trim();save();render()}return}case'edit':editId=id;return go('edit');case'newitem':editId=null;return go('edit');case'bulk':return startBulk();case'bulkadd':captureBulk();bulkDraft.push({ref:'',text:'',lang:'ko-KR',translation:'개역개정'});return bulkPage();case'bulkremove':captureBulk();bulkDraft.splice(Number(id),1);return bulkPage();case'bulkparse':return parseBulk();case'bulkpreview':return previewBulk();case'bulkback':return bulkPage();case'bulkcommit':return commitBulk();case'trash':if(item(id)?.plan==='yes')return toast('공식 말씀은 관리자만 변경할 수 있습니다.');if(confirm('이 항목을 삭제할까요? 48시간 동안 복구할 수 있습니다.')){let x=item(id);db.trash.push({...x,deleted:Date.now()});db.items=db.items.filter(y=>y.id!==id);save();go('detail')}return;case'recover':{let x=db.trash.find(y=>y.id===id);if(x){delete x.deleted;db.items.push(x);db.trash=db.trash.filter(y=>y.id!==id);save();render()}return}case'fav':item(id).favorite=!item(id).favorite;save();return render();case'startplan':return start(scoped(id));case'startitem':return start(scoped('item:'+id));case'review':return start(due());case'favoriteStudy':return start(scoped('fav'));case'mode':{let xs=scoped($('#scope').value);if(!xs.length)return toast($('#scope').value==='fav'?'별표를 눌러 본문이 등록된 말씀을 즐겨찾기에 추가하세요.':'학습 범위에 본문이 등록된 말씀이 없습니다.');return start(xs,id,$('#difficulty').value,$('#shuffle').checked)}case'flip':session.q.flip=!session.q.flip;return render();case'rate':{let x=item(session.ids[session.index]);logAttempt(x,null,id,'self',false);return nextQuestion()}case'pick':session.q.selected.push(Number(id));return render();case'unpick':session.q.selected=session.q.selected.filter(i=>i!==Number(id));return render();case'hintshow':session.q.hint=true;return render();case'grade':return grade();case'next':return nextQuestion();case'endstudy':if(confirm('학습을 종료할까요? 완료한 기록은 저장됩니다.'))go('result');return;case'listenplan':audioState.scope=id;go('listen');return playAudio(id);case'play':return playAudio($('#audioScope').value);case'pause':if(audioState.active){audioState.paused=!audioState.paused;if(mainAudio){if(audioState.paused)mainAudio.pause();else await mainAudio.play()}else if(window.speechSynthesis){if(audioState.paused)speechSynthesis.pause();else speechSynthesis.resume()}audioUI()}return;case'stop':return stopAudio();case'recordplay':{let b=document.querySelector(`[data-act="recordplay:${id}"]`),a=b?.parentElement.querySelector('audio');if(!a)return;if(a.paused){await a.play();b.textContent='Ⅱ 일시정지'}else{a.pause();b.textContent='▶ 듣기'}a.ontimeupdate=()=>{let t=Math.floor(a.currentTime);b.parentElement.querySelector('.record-time').textContent=Math.floor(t/60)+':'+String(t%60).padStart(2,'0')};a.onpause=()=>b.textContent='▶ 듣기';a.onended=()=>b.textContent='▶ 듣기';return}case'recstart':return recStartFn();case'recstop':if(recording?.state==='recording')recording.stop();return;case'reccompare':if(recording)return toast('녹음을 먼저 종료하세요.');return playAudio('item:'+$('#recItem').value);case'recdelete':if(confirm('녹음을 삭제할까요?')){await recOp('readwrite',s=>s.delete(id));record()}return;case'recrename':{let r=await recOp('readonly',s=>s.get(id)),name=prompt('녹음 이름',r.name);if(name?.trim()){r.name=name.trim();await recOp('readwrite',s=>s.put(r));record()}return}case'recdownload':{let r=await recOp('readonly',s=>s.get(id));download(r.blob,r.name+'.'+(r.blob.type.includes('mp4')?'m4a':r.blob.type.includes('ogg')?'ogg':'webm'));return}case'backup':return download(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'yes-word-'+day()+'.json');case'restore':return $('#restorefile').click()}}
'use strict';
// Community UI runs inside the authenticated app, uses only RLS/RPC protected endpoints.
const communityClient=()=>window.YES_CLIENT;
let communityAdmin=false,communityGroups=[],communityPlayer=null,communityEpoch=0,communityRecorder=null,communityStream=null;
const englishRefs=['2 Timothy 3:16–17','Joshua 1:8','John 16:24','Revelation 1:8',"The Lord's Prayer",'Matthew 16:16',"Apostles' Creed",'Romans 5:8','John 7:37–38','Ephesians 2:8','Matthew 22:37–38','Matthew 22:39','1 John 2:17','1 Corinthians 15:57–58','Ephesians 4:3–4'];
function communityStop(){communityEpoch++;officialClean();if(communityPlayer){communityPlayer.pause();communityPlayer.removeAttribute('src');communityPlayer=null}if(communityRecorder&&communityRecorder.state==='recording')communityRecorder.stop();communityStream?.getTracks().forEach(t=>t.stop());communityStream=null}
function must(r){if(r.error)throw r.error;return r.data}
function onlineCommunity(){if(!communityClient()||!navigator.onLine)throw Error('온라인에서 로그인한 후 사용하세요.');return communityClient()}
async function adminCheck(){if(isGuest)return false;try{communityAdmin=must(await onlineCommunity().rpc('yw_is_admin'))===true}catch{communityAdmin=false}await refreshOfficialSetting();return communityAdmin}
function communityNav(){if(isGuest)return btn('Google 로그인으로 공동체 참여','guestlogin','outline full');return (communityAdmin?btn('관리자 대시보드','goto:admin','primary full'):'')+btn('YES 공동체','goto:community','outline full')+(officialEnabled?btn('공식 말씀 음성','goto:official','outline full'):'')}
function communityError(e){toast(e?.message||'처리하지 못했습니다.');}
function safeUuid(v){return typeof v==='string'&&/^[a-f0-9-]{36}$/i.test(v)}
function field(id){return document.getElementById(id)?.value||''}
function cmButton(label,act,cls='outline'){return btn(label,act,cls)}
function cmDate(v){return v?new Date(v).toLocaleString('ko-KR'):'—'}
async function adminPage(){let epoch=++communityEpoch;app.innerHTML=heading('Administration','관리자')+'<p>권한 확인 중…</p>';try{if(!await adminCheck())throw Error('관리자만 접근할 수 있습니다.');await refreshWeeklyConfig();let c=onlineCommunity(),[users,groups,curriculum,audios]=await Promise.all([c.rpc('yw_admin_users'),c.from('yw_groups').select('*').order('created_at',{ascending:false}),c.from('official_curriculum').select('*').order('lesson'),c.from('official_audio').select('*').order('created_at',{ascending:false})]).then(rs=>rs.map(must));let textResult=await c.from('official_texts').select('*').order('item_key');if(page!=='admin'||epoch!==communityEpoch)return;let recent=users.filter(u=>u.last_login&&day(new Date(u.last_login))===day()).length;app.innerHTML=btn('← MY','goto:my','outline')+heading('Administration','YES WORD 관리자')+weeklyAdminPanel()+btn('Report Issue · 접수된 오류','goto:issuereports','outline full')+'<div class="grid"><section class="card"><small>가입 계정</small><div class="metric">'+users.length+'</div></section><section class="card"><small>오늘 로그인</small><div class="metric">'+recent+'</div></section></div><h2>공식 말씀 및 음성 자료</h2>'+officialContentPanel(curriculum,audios,textResult)+'<h2>가입 사용자</h2>'+users.map(u=>'<section class="card"><b>'+esc(u.display_name||'프로필 미등록')+'</b><p>'+esc(u.email)+'</p><small>'+esc(u.affiliation||'')+' · 가입 '+esc(cmDate(u.joined_at))+' · 마지막 백업 '+esc(cmDate(u.backup_at))+'</small></section>').join('')+'<h2>그룹 관리</h2><section class="card stack"><input id="new-group" placeholder="2027 상반기 새일꾼반"><button data-act="cmcreate" class="primary">그룹 생성</button></section>'+groups.map(g=>'<section class="card"><h3>'+esc(g.name)+'</h3><small>'+(g.active?'운영 중':'종료')+'</small><div class="stack">'+btn('명단 및 리더 설정','cmroster:'+g.id,'outline')+btn('7일 초대 코드 생성','cminvite:'+g.id,'outline')+btn(g.active?'그룹 종료':'그룹 재개','cmtoggle:'+g.id,'outline')+'</div></section>').join('')+'<h2>암송 과정 관리</h2><p class="muted">공식 주소 13개와 과별 제목을 관리합니다. 본문 및 음성 일괄 등록은 위의 공식 자료 관리에서 진행하세요.</p>'+curriculum.map(x=>'<section class="card"><small>'+x.lesson+'과</small><b>'+esc(x.reference_ko)+'</b><p>'+esc(x.reference_en)+'</p><p>'+esc(x.lesson_title)+'</p>'+btn('과 제목 편집','cmtitle:'+x.item_key,'outline')+'</section>').join('')+'<h2>공식 음성 관리</h2>'+serviceSettingsPanel()+'<h2>공식 음성 등록</h2><section class="card stack"><label>암송 항목</label><select id="official-item">'+options(curriculum.map(x=>[x.item_key,x.reference_ko]),curriculum[0]?.item_key)+'</select><label>언어</label><select id="official-lang"><option value="ko-KR">한국어</option><option value="en-US">English</option></select><label>음성 제목</label><input id="official-title" maxlength="120" placeholder="공식 암송 음성"><label>사용 허가를 받은 음성만 업로드하세요.</label><input type="file" id="official-file" accept="audio/*,video/webm"><small data-audio-file-info role="status">파일을 선택하지 않았습니다.</small><button class="primary" data-act="cmupload">파일 등록 및 즉시 공개</button><button class="outline" data-act="cmuploaddraft">비공개 초안 등록</button><button class="outline" data-act="cmrecord">직접 녹음 시작</button><button class="outline" data-act="cmrecordstop">녹음 종료 및 초안 저장</button></section>'+audios.map(a=>'<section class="card"><b>'+esc(a.title)+'</b><p>'+esc(a.item_key)+' · '+esc(a.language)+' · '+(a.published?'공개':'초안')+'</p>'+btn('미리 듣기','cmplay:'+a.id,'outline')+btn(a.published?'비공개 전환':'공개하기','cmpublish:'+a.id,'outline')+btn('삭제','cmdeleteaudio:'+a.id,'outline')+'</section>').join('');}catch(e){if(page==='admin'&&epoch===communityEpoch)app.innerHTML=heading('Administration','관리자')+'<section class="card">'+esc(e.message)+'<p>'+btn('돌아가기','goto:my','outline')+'</p></section>'}}
async function communityPage(){let epoch=++communityEpoch;app.innerHTML=heading('Community','YES 공동체')+'<p>불러오는 중…</p>';try{let c=onlineCommunity(),[groups,members]=await Promise.all([c.from('yw_groups').select('*'),c.from('yw_members').select('group_id,role').eq('user_id',identity.id)]).then(rs=>rs.map(must));if(page!=='community'||epoch!==communityEpoch)return;communityGroups=groups.filter(g=>members.some(m=>m.group_id===g.id));app.innerHTML=btn('← MY','goto:my','outline')+heading('Community','YES 공동체')+'<section class="card stack"><h3>그룹 참여</h3><input id="group-code" placeholder="리더에게 받은 초대 코드"><button class="primary" data-act="cmjoin">가입하기</button></section>'+communityGroups.map(g=>'<section class="card"><h3>'+esc(g.name)+'</h3><small>'+esc(members.find(m=>m.group_id===g.id)?.role==='leader'?'담당 리더':'학생')+'</small><p>새일꾼반 15개 기본 항목의 요약 진척도만 공유합니다.</p>'+btn('내 진척도 제출','cmprogress:'+g.id,'primary full')+btn('그룹 녹음 및 피드백','cmsubmissions:'+g.id,'outline full')+(members.find(m=>m.group_id===g.id)?.role==='leader'?btn('학생 진척도 보기','cmroster:'+g.id,'outline full'):'')+'</section>').join('')+(communityGroups.length?'':'<p class="muted">가입한 그룹이 없습니다.</p>');}catch(e){if(page==='community'&&epoch===communityEpoch)app.innerHTML=heading('Community','YES 공동체')+'<section class="card">'+esc(e.message)+'</section>'}}
let officialRows=[],officialUrl=null,officialCancel=null,officialPaused=false,officialActive=false;
const officialDB=()=>new Promise((ok,no)=>{let q=indexedDB.open('yw-official-cache:'+identity.id,1);q.onupgradeneeded=()=>q.result.createObjectStore('audio',{keyPath:'id'});q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)});
async function officialOp(mode,fn){let d=await officialDB();try{return await new Promise((ok,no)=>{let tx=d.transaction('audio',mode),q=fn(tx.objectStore('audio'));tx.oncomplete=()=>ok(q.result);tx.onerror=()=>no(tx.error);tx.onabort=()=>no(tx.error)})}finally{d.close()}}
function officialStatus(t){let e=$('#official-status');if(e)e.textContent=t}
function officialClean(){officialActive=false;officialPaused=false;if(officialCancel){let f=officialCancel;officialCancel=null;f(false)}if(officialUrl){URL.revokeObjectURL(officialUrl);officialUrl=null}}
async function officialPage(){let previous=Object.fromEntries(['official-repeat','official-speed','official-gap','official-language'].map(id=>[id,$('#'+id)?.value]));let epoch=++communityEpoch;await refreshOfficialSetting();if(page!=='official'||epoch!==communityEpoch)return;if(!officialEnabled){app.innerHTML=heading('Audio','공식 말씀 음성')+'<section class="card">공식 음성 서비스가 현재 제공되지 않습니다.</section>'+btn('← 말씀 듣기','goto:listen','outline full');return;}app.innerHTML=heading('Audio','공식 말씀 음성')+'<p>불러오는 중…</p>';try{let saved=await officialOp('readonly',s=>s.getAll()).catch(()=>[]),online=!!window.YES_CLIENT&&navigator.onLine;let rows;if(online){let c=onlineCommunity();rows=must(await c.from('official_audio').select('id,item_key,language,title,object_path,created_at').eq('published',true).order('created_at'));let live=new Set(rows.map(a=>a.id));for(let a of saved.filter(x=>!live.has(x.id)))await officialOp('readwrite',s=>s.delete(a.id));saved=saved.filter(x=>live.has(x.id))}else rows=saved.map(x=>x.meta);if(page!=='official'||epoch!==communityEpoch)return;let latest=new Map();for(let a of rows.slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))){let k=a.item_key+'|'+a.language;if(!latest.has(k))latest.set(k,a)}officialRows=Array.from(latest.values()).sort((a,b)=>Number(a.item_key.slice(4))-Number(b.item_key.slice(4))||a.language.localeCompare(b.language));let ids=new Set(saved.map(x=>x.id));app.innerHTML=btn('← 듣기','goto:listen','outline')+heading('Audio','공식 말씀 음성')+'<p class="muted">'+(online?'관리자가 공개한 암송 음성입니다. 다운로드한 음성은 오프라인에서도 들을 수 있습니다.':'오프라인 · 이 계정에 다운로드한 음성만 표시합니다.')+'</p><section class="card stack"><h3>암송 플레이어</h3><p id="official-status" role="status">재생 대기</p><div class="grid"><div><label>반복 횟수</label><select id="official-repeat">'+options([1,3,5,10].map(n=>[n,n+'회']),3)+'</select></div><div><label>속도</label><select id="official-speed">'+options([.75,.9,1,1.15,1.25].map(n=>[n,n+'×']),1)+'</select></div><div><label>반복 사이 휴식</label><select id="official-gap">'+options([0,3,5,10].map(n=>[n,n+'초']),3)+'</select></div><div><label>언어</label><select id="official-language">'+options([['all','전체'],['ko-KR','한국어'],['en-US','English']],'ko-KR')+'</select></div></div>'+btn('순서대로 연속 듣기','officialqueue','primary full')+'<div class="row">'+btn('일시정지 / 계속','officialpause','outline grow')+btn('정지','officialstop','outline')+'</div></section>'+officialRows.map(a=>'<section class="card"><b>'+esc(a.title)+'</b><p>'+esc(a.language==='en-US'?englishRefs[Number(a.item_key.slice(4))]:refs[Number(a.item_key.slice(4))])+' · '+(a.language==='en-US'?'영어':'한국어')+'</p><small>'+(ids.has(a.id)?'오프라인 저장 완료':'온라인 음성')+'</small><div class="row">'+btn('재생','officialsingle:'+a.id,'primary grow')+(ids.has(a.id)?btn('기기 저장 삭제','officialremove:'+a.id,'outline'):online?btn('오프라인 저장','officialdownload:'+a.id,'outline'):'')+'</div></section>').join('')+(rows.length?'':'<section class="card">등록된 음성이 없습니다.</section>');for(let [id,value] of Object.entries(previous)){let el=$('#'+id);if(el&&value!==undefined)el.value=value}}catch(e){if(page==='official'&&epoch===communityEpoch)app.innerHTML=btn('← 듣기','goto:listen','outline')+heading('Audio','공식 말씀 음성')+'<section class="card">'+esc(e.message||'음성 목록을 불러오지 못했습니다.')+'</section>'}}
async function guestOfficialFetch(path,blob=false){let r=await fetch('https://nheaxjxixixhmhxinqlt.supabase.co/'+path,{headers:{apikey:'sb_publishable_ORcSnStmZXAuyRxrqtLOTA_ZjJz7naH'},cache:'no-store'});if(!r.ok)throw Error('공식 음성 연결 실패 ('+r.status+')');return blob?r.blob():r.json()}
async function officialBlob(a){if(isGuest&&navigator.onLine)return guestOfficialFetch('storage/v1/object/authenticated/yw-official-audio/'+a.object_path.split('/').map(encodeURIComponent).join('/'),true);let cached=await officialOp('readonly',s=>s.get(a.id)).catch(()=>null);if(cached?.blob&&cached.meta?.object_path===a.object_path)return cached.blob;return must(await onlineCommunity().storage.from('yw-official-audio').download(a.object_path))}
async function officialPlay(rows){if(!rows.length)return toast('재생할 음성이 없습니다.');let repeat=Math.max(1,Math.min(10,Number(field('official-repeat'))||1)),speed=Number(field('official-speed'))||1,gap=Number(field('official-gap'))||0;stopAllPlayback();let epoch=communityEpoch;officialActive=true;let alive=()=>officialActive&&epoch===communityEpoch&&page==='official';try{for(let i=0;i<rows.length&&alive();i++){let a=rows[i];officialStatus('불러오는 중 · '+a.title);let blob=await officialBlob(a);if(!alive())return;officialUrl=URL.createObjectURL(blob);for(let j=0;j<repeat&&alive();j++){while(officialPaused&&alive())await sleep(100);if(!alive())return;officialStatus(a.title+' · '+(i+1)+'/'+rows.length+' · 반복 '+(j+1)+'/'+repeat);let player=new Audio(officialUrl);communityPlayer=player;player.playbackRate=speed;let ok=await new Promise((resolve,reject)=>{officialCancel=resolve;player.onended=()=>resolve(true);player.onerror=()=>reject(Error('음성 파일 재생 실패'));player.play().catch(reject)});officialCancel=null;if(!ok||!alive())return;communityPlayer=null;if(j<repeat-1||i<rows.length-1){for(let t=0;t<gap*10&&alive();){await sleep(100);if(!officialPaused)t++}}}if(officialUrl){URL.revokeObjectURL(officialUrl);officialUrl=null}}if(alive())officialStatus('재생 완료')}catch(e){if(alive()){officialStatus('재생 중단 · '+(e.message||'다시 시도하세요.'));toast('재생 버튼을 다시 눌러 주세요.')}}finally{if(epoch===communityEpoch){if(communityPlayer)communityPlayer.pause();communityPlayer=null;officialClean()}}}
async function officialAction(k,id){if(!['officialstop','officialremove'].includes(k)){await refreshOfficialSetting();if(page!=='official')return;if(!officialEnabled){stopAllPlayback();return officialPage()}}let a=officialRows.find(x=>x.id===id);switch(k){case'officialqueue':return officialPlay(officialRows.filter(x=>field('official-language')==='all'||x.language===field('official-language')));case'officialsingle':if(a)return officialPlay([a]);return;case'officialstop':stopAllPlayback();officialStatus('재생 정지');return;case'officialpause':if(!officialActive)return;officialPaused=!officialPaused;if(communityPlayer){if(officialPaused)communityPlayer.pause();else await communityPlayer.play()}officialStatus(officialPaused?'일시정지':'재생 중');return;case'officialdownload':if(!a)return;{let c=onlineCommunity(),epoch=communityEpoch;let live=must(await c.from('official_audio').select('id').eq('id',id).eq('published',true).single());if(!live)return;let blob=must(await c.storage.from('yw-official-audio').download(a.object_path));if(blob.size>15000000)throw Error('파일 크기 초과');await officialOp('readwrite',s=>s.put({id:a.id,meta:a,blob}));toast('오프라인 저장 완료');if(page==='official'&&epoch===communityEpoch){stopAllPlayback();return officialPage()}}return;case'officialremove':await officialOp('readwrite',s=>s.delete(id));stopAllPlayback();return officialPage()}}

let cmGroup=null,cmReturn='community';
async function rosterPage(g){let epoch=++communityEpoch;cmGroup=g;app.innerHTML=heading('Group','그룹 명단')+'<p>불러오는 중…</p>';try{let c=onlineCommunity(),rows=must(await c.rpc('yw_group_roster',{g}));if(page!=='roster'||epoch!==communityEpoch)return;let admin=await adminCheck();if(page!=='roster'||epoch!==communityEpoch)return;app.innerHTML=btn('← 돌아가기','goto:'+cmReturn,'outline')+heading('Group','그룹 명단 및 진척도')+'<p class="muted">학생이 제출한 요약입니다. 미제출 기록은 —로 표시됩니다.</p>'+rows.map(u=>'<section class="card"><b>'+esc(u.display_name||'이름 미등록')+'</b><p>'+esc(u.role)+' · '+(u.completed??'—')+' / 13 완료 · '+(u.attempts??'—')+'회 학습</p><small>'+esc(cmDate(u.reported_at))+'</small>'+(admin?btn(u.role==='leader'?'학생으로 변경':'리더로 지정','cmrole:'+u.user_id,'outline')+btn('그룹에서 제거','cmremove:'+u.user_id,'outline'):'')+'</section>').join('');}catch(e){if(page==='roster'&&epoch===communityEpoch)app.innerHTML=heading('Group','그룹 명단')+esc(e.message)}}
async function submissionsPage(g){let epoch=++communityEpoch;cmGroup=g;app.innerHTML=heading('Recite','그룹 녹음')+'<p>불러오는 중…</p>';try{let c=onlineCommunity(),[rows,feedback,lead]=await Promise.all([c.from('yw_submissions').select('*').eq('group_id',g),c.from('yw_feedback').select('*'),c.rpc('yw_is_leader',{g})]).then(rs=>rs.map(must));let recordings=await recOp('readonly',s=>s.getAll());if(page!=='submissions'||epoch!==communityEpoch)return;app.innerHTML=btn('← 공동체','goto:community','outline')+heading('Recite','그룹 녹음 및 피드백')+'<section class="card stack"><p>선택한 녹음만 이 그룹의 담당 리더에게 공유됩니다.</p><select id="submit-recording">'+options(recordings.map(r=>[r.id,r.name]),recordings[0]?.id)+'</select>'+btn('선택한 녹음 제출','cmsubmit','primary')+'</section>'+rows.map(r=>'<section class="card"><b>'+esc(r.reference)+'</b><p>'+esc(cmDate(r.created_at))+' · '+(r.user_id===identity.id?'내 제출':'학생 제출')+'</p>'+btn('듣기','cmsubplay:'+r.id,'outline')+btn('정지','cmstop','outline')+'<p>'+esc(feedback.find(f=>f.submission_id===r.id)?.body||'아직 피드백 없음')+'</p>'+(lead?btn('피드백 작성','cmfeedback:'+r.id,'outline'):'')+(r.user_id===identity.id?btn('제출 취소','cmwithdraw:'+r.id,'outline'):'')+'</section>').join('');}catch(e){if(page==='submissions'&&epoch===communityEpoch)app.innerHTML=heading('Recite','그룹 녹음')+esc(e.message)}}
async function uploadOfficial(blob,itemKey,language,title,refresh=true,publish=false){let c=onlineCommunity();if(!await adminCheck())throw Error('관리자 권한이 필요합니다.');let fileError=audioFileError(blob);if(fileError)throw Error(fileError);if(!title.trim())throw Error('음성 제목을 입력하세요.');let path=identity.id+'/'+crypto.randomUUID();must(await c.storage.from('yw-official-audio').upload(path,blob,{contentType:blob.type||'audio/mpeg',upsert:false}));try{must(await c.from('official_audio').insert({item_key:itemKey,language,title:title.trim(),object_path:path,published:publish}))}catch(e){await c.storage.from('yw-official-audio').remove([path]);throw e}if(refresh){toast(publish?'공식 음성 등록 및 공개 완료':'공식 음성 초안 등록 완료');if(page==='admin')return adminPage()}}
async function playCommunity(bucket,path){let c=onlineCommunity();stopAllPlayback();let epoch=communityEpoch;let data=must(await c.storage.from(bucket).createSignedUrl(path,120));if(epoch!==communityEpoch)return;communityPlayer=new Audio(data.signedUrl);await communityPlayer.play();toast('음성 재생 중')}
async function communityAction(k,id){let c=onlineCommunity();
 switch(k){
 case'cmcreate':{let name=field('new-group').trim();if(!name)return toast('그룹 이름을 입력하세요.');must(await c.from('yw_groups').insert({name}));return adminPage()}
 case'cmtoggle':{let g=must(await c.from('yw_groups').select('active').eq('id',id).single());if(!confirm(g.active?'그룹을 종료할까요?':'그룹을 재개할까요?'))return;must(await c.from('yw_groups').update({active:!g.active}).eq('id',id));return adminPage()}
 case'cminvite':{let code=crypto.randomUUID().replace(/-/g,'');must(await c.rpc('yw_set_invite',{g:id,code}));prompt('7일 유효 초대 코드 (기존 코드는 만료됩니다)',code);return}
 case'cmjoin':{must(await c.rpc('yw_join_group',{code:field('group-code').trim().toLowerCase()}));toast('가입 완료');return communityPage()}
 case'cmroster':cmGroup=id;cmReturn=page==='admin'?'admin':'community';return go('roster');
 case'cmrole':{let row=must(await c.from('yw_members').select('role').eq('group_id',cmGroup).eq('user_id',id).single());if(!confirm('그룹 역할을 변경할까요?'))return;must(await c.from('yw_members').update({role:row.role==='leader'?'student':'leader'}).eq('group_id',cmGroup).eq('user_id',id));return rosterPage(cmGroup)}
 case'cmremove':if(confirm('이 회원을 그룹에서 제거할까요?')){must(await c.from('yw_members').delete().eq('group_id',cmGroup).eq('user_id',id));return rosterPage(cmGroup)}return;
 case'cmtitle':{let title=prompt('과 제목');if(title===null)return;must(await c.from('official_curriculum').update({lesson_title:title.trim()}).eq('item_key',id));return adminPage()}
 case'cmprogress':{if(!confirm('기본 13개 항목의 완료 수, 입력 수, 학습 횟수를 담당 리더에게 공유할까요?'))return;let xs=db.items.filter(x=>officialIds.has(x.id)),keys=new Set(xs.map(x=>x.id));must(await c.from('yw_group_progress').upsert({group_id:id,user_id:identity.id,completed:xs.filter(complete).length,entered:xs.filter(x=>x.text.trim()).length,attempts:db.attempts.filter(a=>keys.has(a.item)).length,updated_at:new Date().toISOString()}));return toast('요약 진척도 제출 완료')}
 case'cmcontentlang':if(!['ko-KR','en-US'].includes(id)||id===adminContentLanguage||officialBatchBusy)return;if(!confirm('언어를 전환할까요? 저장하지 않은 입력은 유지되지 않습니다.'))return;adminContentLanguage=id;return adminPage();case'cmtextoff':return unpublishLanguage();case'cmtextsave':return saveOfficialTexts();
 case'cmtextpublish':return publishOfficialTexts();
 case'cmtextunpublish':return unpublishOfficialText(id);
 case'cmbulkaudio':return uploadOfficialBatch(true);
 case'cmbulkaudiodraft':return uploadOfficialBatch(false);
 case'cmbulkpublish':return publishOfficialAudioBatch();
 case'cmupload':case'cmuploaddraft':{let publish=k==='cmupload',input=document.getElementById('official-file'),error=audioFileError(input?.files[0]);if(error){if(input)showAudioFileInfo(input);return toast(error)}if(publish&&!confirm('음성 배포 권한을 확인했나요? 등록 즉시 회원과 게스트에게 공개됩니다.'))return;return uploadOfficial(document.getElementById('official-file')?.files[0],field('official-item'),field('official-lang'),field('official-title'),true,publish)}
 case'cmrecord':{if(communityRecorder?.state==='recording')return;let key=field('official-item'),lang=field('official-lang'),title=field('official-title');if(!title.trim())return toast('제목을 먼저 입력하세요.');if(!await adminCheck())throw Error('권한 없음');let epoch=communityEpoch;communityStream=await navigator.mediaDevices.getUserMedia({audio:true});if(page!=='admin'||epoch!==communityEpoch){communityStream.getTracks().forEach(t=>t.stop());return}let chunks=[],r=new MediaRecorder(communityStream);communityRecorder=r;r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.onstop=()=>{communityStream?.getTracks().forEach(t=>t.stop());communityStream=null;communityRecorder=null;if(page==='admin'&&epoch===communityEpoch)uploadOfficial(new Blob(chunks,{type:r.mimeType||'audio/webm'}),key,lang,title).catch(communityError)};r.start();setTimeout(()=>{if(r.state==='recording')r.stop()},300000);return toast('공식 음성 녹음 중')}
 case'cmrecordstop':if(communityRecorder?.state==='recording')communityRecorder.stop();return;
 case'cmplay':{let a=must(await c.from('official_audio').select('object_path').eq('id',id).single());return playCommunity('yw-official-audio',a.object_path)}
 case'cmstop':return stopAllPlayback();
 case'cmpublish':{let a=must(await c.from('official_audio').select('published').eq('id',id).single());if(!a.published&&!confirm('본문 및 음성 배포에 필요한 권한을 확인했나요? 회원과 게스트에게 공개합니다.'))return;must(await c.from('official_audio').update({published:!a.published}).eq('id',id));return adminPage()}
 case'cmdeleteaudio':{if(!confirm('공식 음성을 삭제할까요?'))return;let a=must(await c.from('official_audio').select('object_path').eq('id',id).single());must(await c.from('official_audio').delete().eq('id',id));let removal=await c.storage.from('yw-official-audio').remove([a.object_path]);if(removal.error)toast('목록 삭제 완료, 파일 정리 필요');return adminPage()}
 case'cmsubmissions':cmGroup=id;return go('submissions');
 case'cmsubmit':{let rec=await recOp('readonly',s=>s.get(field('submit-recording')));if(!rec||!rec.blob||rec.blob.size>15000000)return toast('15MB 이하의 녹음을 선택하세요.');if(!confirm('이 녹음만 담당 리더에게 제출할까요?'))return;let g=cmGroup,sid=crypto.randomUUID(),path=identity.id+'/'+g+'/'+sid;must(await c.from('yw_submissions').insert({id:sid,group_id:g,user_id:identity.id,reference:(item(rec.item)?.ref||rec.name).slice(0,200),object_path:path}));try{must(await c.storage.from('yw-submissions').upload(path,rec.blob,{contentType:rec.blob.type||'audio/webm',upsert:false}))}catch(e){await c.from('yw_submissions').delete().eq('id',sid);throw e}toast('녹음 제출 완료');return submissionsPage(g)}
 case'cmsubplay':{let a=must(await c.from('yw_submissions').select('object_path').eq('id',id).single());return playCommunity('yw-submissions',a.object_path)}
 case'cmwithdraw':{if(!confirm('제출을 취소할까요? 기존에 발급된 재생 링크는 최대 2분간 유효할 수 있습니다.'))return;let a=must(await c.from('yw_submissions').select('object_path').eq('id',id).single());must(await c.from('yw_submissions').delete().eq('id',id));let r=await c.storage.from('yw-submissions').remove([a.object_path]);if(r.error)toast('접근 권한 취소 완료, 파일 정리 필요');return submissionsPage(cmGroup)}
 case'cmfeedback':{let body=prompt('학생에게 보낼 피드백 (최대 2000자)');if(!body?.trim())return;must(await c.from('yw_feedback').upsert({submission_id:id,reviewer_id:identity.id,body:body.trim().slice(0,2000),updated_at:new Date().toISOString()}));return submissionsPage(cmGroup)}
 }
}


let favFilter='all',selectedStudy=new Set(),studyScope='weekly',bulkDraft=[],bulkPreview=null;
function wrongItems(){return filled().filter(x=>{let a=db.attempts.slice().reverse().find(y=>matchesAttempt(y,x)&&Number.isFinite(y.score)&&!y.hint&&y.version===x.version);return a&&a.score<90})}
function favoritesPage(){let xs=favFilter==='fav'?db.items.filter(x=>x.favorite):db.items;app.innerHTML=btn('← 암송 훈련','goto:study','outline')+heading('Library','나의 즐겨찾기')+'<p>별표를 눌러 자주 암송할 말씀을 모으세요. 본문을 입력한 말씀만 훈련할 수 있습니다.</p><div class="row">'+btn('전체 말씀','favfilter:all','outline grow')+btn('즐겨찾기 ('+db.items.filter(x=>x.favorite).length+')','favfilter:fav','outline grow')+'</div>'+xs.map(x=>'<section class="card"><div class="row between"><div><small>'+esc(plan(x.plan)?.title||'')+' · '+(x.text.trim()?'본문 등록':'본문 입력 대기')+'</small><h3>'+esc(x.ref)+'</h3></div>'+btn(x.favorite?'★ 저장됨':'☆ 추가','fav:'+x.id,'outline','aria-pressed="'+Boolean(x.favorite)+'"')+'</div></section>').join('')+(xs.length?'':'<section class="card">즐겨찾기가 없습니다. 전체 말씀에서 별표를 눌러 주세요.</section>')+btn('즐겨찾기 '+filled().filter(x=>x.favorite).length+'개 암송','favtrain','primary full')}
function studyScopeUI(){let e=$('#scope-guide');if(!e)return;let v=$('#scope').value;e.innerHTML='<p>학습 가능한 말씀 '+scoped(v).length+'개</p>'+(v==='fav'?'<p>플랜의 ☆ 또는 즐겨찾기 관리에서 추가할 수 있습니다.</p>':v==='wrong'?'<p>최근 힌트 없는 채점에서 90점 미만인 말씀입니다.</p>':v==='selected'?'<p>암송할 말씀을 직접 선택하세요.</p>'+filled().map(x=>'<label style="display:block"><input type="checkbox" data-study-id="'+esc(x.id)+'" '+(selectedStudy.has(x.id)?'checked':'')+'> '+esc(x.ref)+'</label>').join(''):'');e.querySelectorAll('[data-study-id]').forEach(el=>el.onchange=()=>{if(el.checked)selectedStudy.add(el.dataset.studyId);else selectedStudy.delete(el.dataset.studyId);studyScopeUI()})}
function startBulk(){bulkDraft=db.items.filter(x=>x.plan===currentPlan&&!x.text.trim()).map(x=>({id:x.id,ref:x.ref,text:'',lang:x.lang||'ko-KR',translation:x.translation||'개역개정'}));if(!bulkDraft.length)bulkDraft=[{ref:'',text:'',lang:'ko-KR',translation:'개역개정'}];bulkPreview=null;go('bulkpage')}
function captureBulk(){document.querySelectorAll('[data-bulk-index]').forEach(el=>{let i=Number(el.dataset.bulkIndex);if(bulkDraft[i])bulkDraft[i][el.dataset.field]=el.value})}
function bulkPage(){if(!plan(currentPlan))return go('plans');app.innerHTML=btn('← 플랜','goto:detail','outline')+heading('Library','말씀 일괄 등록')+'<section class="card"><h3>등록 방법</h3><p>성경 주소와 본문을 별도 입력란에 붙여넣으세요. 본문 줄바꿈은 유지됩니다. 빈 항목은 등록하지 않습니다.</p><details><summary>정리된 자료 한꺼번에 붙여넣기</summary><p>첫 줄은 성경 주소, 다음 줄부터 본문입니다. 구절 사이는 빈 줄로 구분하세요. 또는 주소 | 본문 형식으로 한 줄씩 입력하세요.</p><pre>로마서 5:8\n[본문 붙여넣기]\n\n여호수아 1:8\n[본문 붙여넣기]</pre><textarea id="bulk-paste" rows="6" placeholder="정리된 자료 붙여넣기"></textarea>'+btn('입력란으로 변환','bulkparse','outline full')+'</details></section>'+bulkDraft.map((r,i)=>'<section class="card stack"><div class="row between"><b>말씀 '+(i+1)+'</b>'+btn('제거','bulkremove:'+i,'outline')+'</div><label>성경 주소</label><input data-bulk-index="'+i+'" data-field="ref" value="'+esc(r.ref)+'" '+(r.id?'readonly':'')+' placeholder="예: 로마서 5:8"><label>번역본</label><select data-bulk-index="'+i+'" data-field="translation">'+options([['개역개정','개역개정'],['ESV','ESV'],['기타','기타']],r.translation)+'</select><label>성경 본문</label><textarea rows="4" data-bulk-index="'+i+'" data-field="text" placeholder="여기에 성경 본문을 붙여넣으세요">'+esc(r.text)+'</textarea></section>').join('')+btn('+ 말씀 입력란 추가','bulkadd','outline full')+btn('등록 전 미리보기','bulkpreview','primary full')}
function refKey(s){return s.normalize('NFKC').replace(/[–—−]/g,'-').replace(/\s+/g,'').toLowerCase()}
function previewBulk(){captureBulk();let rows=bulkDraft.filter(x=>x.text.trim());if(!rows.length)return toast('본문을 하나 이상 입력하세요.');if(rows.some(x=>!x.ref.trim()))return toast('본문이 있는 항목에 주소를 입력하세요.');let seen=new Set();bulkPreview=rows.map(r=>{let lang=r.translation==='ESV'?'en-US':r.translation==='개역개정'?'ko-KR':r.lang||'ko-KR';let existing=r.id?item(r.id):db.items.find(x=>x.plan===currentPlan&&refKey(x.ref)===refKey(r.ref)&&x.lang===lang);let key=existing?.id||lang+':'+refKey(r.ref);let dup=seen.has(key);seen.add(key);return {...r,lang,existing:existing?.id,duplicate:dup,replace:false}});app.innerHTML=heading('Review','일괄 등록 미리보기')+'<p>중복 구절은 기본적으로 기존 본문을 유지합니다. 교체하려면 직접 선택하세요.</p>'+bulkPreview.map((r,i)=>'<section class="card"><b>'+esc(r.ref)+'</b><small>'+esc(r.translation)+'</small><p style="white-space:pre-wrap">'+esc(r.text)+'</p>'+(r.duplicate?'<p>같은 입력 내 중복 · 건너뜀</p>':item(r.existing)?.text.trim()?'<label><input type="checkbox" data-bulk-replace="'+i+'"> 기존 본문 교체</label>':'<p>신규 또는 빈 본문 등록</p>')+'</section>').join('')+btn('← 입력 수정','bulkback','outline full')+btn('확인 및 저장','bulkcommit','primary full')}
function commitBulk(){if(!bulkPreview)return;document.querySelectorAll('[data-bulk-replace]').forEach(e=>bulkPreview[Number(e.dataset.bulkReplace)].replace=e.checked);let n=0;for(let r of bulkPreview){if(r.duplicate)continue;let old=r.existing?item(r.existing):db.items.find(x=>x.plan===currentPlan&&refKey(x.ref)===refKey(r.ref)&&x.lang===r.lang);if(old){if(old.text.trim()&&!r.replace)continue;if(old.text!==r.text||old.translation!==r.translation||old.lang!==r.lang){old.revisions=[...(old.revisions||[]),{text:old.text,ref:old.ref,version:old.version,time:Date.now()}];old.version++;delete db.reviews[old.id]}Object.assign(old,{text:r.text,translation:r.translation,lang:r.lang})}else db.items.push({id:uid(),plan:currentPlan,ref:r.ref.trim(),text:r.text,translation:r.translation,lang:r.lang,version:1,notes:'',favorite:false});n++}save();bulkPreview=null;bulkDraft=[];go('detail');toast(n+'개 말씀 등록 완료')}
function parseBulk(){let raw=$('#bulk-paste')?.value||'';captureBulk();if(!raw.trim())return toast('자료를 붙여넣으세요.');let rows;if(raw.trim().split(/\r?\n/).filter(l=>l.trim()).every(l=>l.includes('|'))){rows=raw.trim().split(/\r?\n/).filter(l=>l.trim()).map(l=>{let p=l.indexOf('|');return {ref:l.slice(0,p).trim(),text:l.slice(p+1).trim()}})}else rows=raw.trim().split(/\r?\n\s*\r?\n/).map(b=>{let lines=b.split(/\r?\n/);return {ref:lines.shift().trim(),text:lines.join('\n').trim()}});if(rows.some(x=>!x.ref||!x.text))return toast('주소와 본문을 확인하고 구절 사이에 빈 줄을 넣어 주세요.');for(let r of rows){let existing=bulkDraft.find(x=>refKey(x.ref)===refKey(r.ref)&&!x.text.trim());if(existing)existing.text=r.text;else bulkDraft.push({...r,lang:'ko-KR',translation:'개역개정'})}bulkPage()}


let officialEnabled=false,officialSettingsReady=false,historyRange='week',historyLimit=30;
async function refreshOfficialSetting(){if(isGuest){if(!navigator.onLine){officialEnabled=false;return}try{let rows=await guestOfficialFetch('rest/v1/yw_service_settings?select=official_audio_enabled&singleton=eq.true');officialEnabled=rows[0]?.official_audio_enabled===true}catch{officialEnabled=false}return}if(!window.YES_CLIENT||!navigator.onLine)return;try{let r=await window.YES_CLIENT.from('yw_service_settings').select('official_audio_enabled').eq('singleton',true).single();if(r.error)throw r.error;officialEnabled=r.data.official_audio_enabled===true;officialSettingsReady=true;localStorage.setItem(storageKey+':official-enabled',String(officialEnabled))}catch{officialEnabled=false;officialSettingsReady=false}}
try{officialEnabled=!isGuest&&localStorage.getItem(storageKey+':official-enabled')==='true'}catch{}
function serviceSettingsPanel(){return '<section class="card stack"><h3>서비스 설정</h3><p>공식 음성 '+(officialEnabled?'활성화':'비활성화')+'</p><p class="muted">비활성화하면 일반 사용자의 새 음성 접근이 차단됩니다. 이미 기기에 저장된 파일은 오프라인에서 즉시 회수할 수 없습니다. 기본 자동 읽기와 개인 녹음은 유지됩니다.</p>'+btn(officialEnabled?'공식 음성 비활성화':'공식 음성 활성화','officialsetting','primary full',officialSettingsReady?'':'disabled')+(officialSettingsReady?'':'<small>관리자 서비스 설정 SQL 적용 필요</small>')+'</section>'}
async function toggleOfficialSetting(){let c=onlineCommunity();if(!await adminCheck()||!officialSettingsReady)return toast('관리자 설정을 확인하세요.');let next=!officialEnabled;if(!confirm(next?'공식 음성 기능을 활성화할까요?':'공식 음성 기능을 비활성화할까요?'))return;must(await c.from('yw_service_settings').update({official_audio_enabled:next}).eq('singleton',true).select('singleton').single());await refreshOfficialSetting();return adminPage()}
let historyLanguage='all';
function historyRows(){let now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(historyRange==='week')start.setDate(start.getDate()-6);if(historyRange==='month')start.setDate(start.getDate()-29);return db.attempts.filter(a=>(historyLanguage==='all'||attemptLanguage(a)===historyLanguage)&&(historyRange==='all'||a.time>=start.getTime())).slice().sort((a,b)=>b.time-a.time)}
function historyRow(a){let x=item(a.item);return '<div class="history-row"><div><strong>'+esc(a.reference||(officialIds.has(a.item)?refLabel(a.item,attemptLanguage(a),'auto'):x?.ref)||'삭제된 말씀')+'</strong><small>'+esc(cmDate(a.time))+' · '+(attemptLanguage(a)==='en-US'?'EN':'KO')+' · '+esc(modes.find(m=>m[0]===a.mode)?.[1]||'암송')+'</small></div><strong class="history-score">'+esc(a.score==null?'자기 평가':a.score+'점')+'</strong></div>'}
function historySummary(){return '<h2>최근 학습 기록</h2><section class="card history-list">'+(db.attempts.length?db.attempts.slice(-5).reverse().map(historyRow).join(''):'<p class="muted">아직 학습 기록이 없습니다.</p>')+btn('전체 학습 History 보기','goto:history','outline full')+'</section>'}
function historyPage(){let rows=historyRows(),scores=rows.filter(a=>Number.isFinite(a.score));let filters=[['today','오늘'],['week','7일'],['month','30일'],['all','전체']];let chart='';if(historyRange!=='all'){let n=historyRange==='today'?1:historyRange==='week'?7:30;let ds=Array.from({length:n},(_,i)=>{let d=new Date();d.setDate(d.getDate()-n+1+i);return {d:day(d),count:rows.filter(a=>day(a.time)===day(d)).length}});let max=Math.max(1,...ds.map(d=>d.count));chart='<section class="card"><h3>학습 횟수</h3><div class="history-chart">'+ds.map(d=>'<div title="'+esc(d.d+' · '+d.count+'회')+'"><i style="height:'+Math.max(2,d.count/max*100)+'%"></i></div>').join('')+'</div><div class="row between"><small>'+ds[0].d+'</small><small>'+ds[ds.length-1].d+'</small></div></section>'}app.innerHTML=btn('← MY','goto:my','outline')+heading('History','학습 기록')+'<div class="row">'+[['all','전체 언어'],['ko-KR','한국어'],['en-US','English']].map(([id,t])=>btn(t,'historylang:'+id,historyLanguage===id?'primary grow':'outline grow')).join('')+'</div><div class="history-filters">'+filters.map(([id,t])=>btn(t,'historyrange:'+id,historyRange===id?'primary':'outline')).join('')+'</div><div class="grid"><div class="card"><small>학습 횟수</small><div class="metric">'+rows.length+'회</div></div><div class="card"><small>평균 채점</small><div class="metric">'+(scores.length?Math.round(scores.reduce((sum,a)=>sum+a.score,0)/scores.length)+'점':'—')+'</div></div></div>'+chart+'<h2>상세 기록</h2><section class="card history-list">'+(rows.length?rows.slice(0,historyLimit).map(historyRow).join(''):'<p class="muted">해당 기간의 학습 기록이 없습니다.</p>')+(rows.length>historyLimit?btn('더 보기','historymore','outline full'):'')+'</section>'}


function guestImportButton(){try{let g=JSON.parse(localStorage.getItem('yes-word-v1:guest-local'));if(!g||localStorage.getItem('yes-word-guest-imported')||!validSnapshot(g)||!nonempty(g))return '';return btn('게스트 학습 기록 가져오기','guestimport','outline full')}catch{return ''}}
async function importGuest(){if(isGuest||!window.YES_CLIENT)return toast('온라인 로그인 후 이용해 주세요.');if(syncBusy)return toast('동기화가 끝난 뒤 다시 시도하세요.');let g;try{g=JSON.parse(localStorage.getItem('yes-word-v1:guest-local'));if(!g||!validSnapshot(g)||!nonempty(g)||localStorage.getItem('yes-word-guest-imported'))return toast('가져올 게스트 기록이 없습니다.');if(nonempty(db))return toast('현재 계정에 학습 기록이 있습니다. 덮어쓰기를 방지하기 위해 가져올 수 없습니다.');let r=await window.YES_CLIENT.from('learning_snapshots').select('user_id').eq('user_id',identity.id).maybeSingle();if(r.error)throw r.error;if(r.data)return toast('서버에 학습 기록이 있습니다. 기존 기록 보호를 위해 가져오기를 중단합니다.');if(!confirm('이 기기의 게스트 기록이 본인의 것인가요? 말씀과 학습 기록을 현재 계정에 복사합니다. 녹음 파일은 게스트 모드에 그대로 보존됩니다.'))return;let next={...initial(),...g,profile:db.profile};localStorage.setItem(storageKey,JSON.stringify(next));localStorage.setItem('yes-word-guest-imported',identity.id);db=next;theme();render();toast('게스트 학습 기록 복사 완료')}catch(e){toast('기록을 가져오지 못했습니다. 기존 기록은 유지됩니다.')}}


/* Official curriculum: licensed administrator-provided text and batch audio. */
let officialBatchBusy=false;
let adminContentLanguage='ko-KR';
function officialContentPanel(curriculum,audios,textResult){
 let language=adminContentLanguage;
 let ready=!textResult.error, rows=ready?textResult.data:[], sorted=curriculum.slice().sort((a,b)=>Number(a.item_key.slice(4))-Number(b.item_key.slice(4)));
 return '<section class="card stack"><h3>공식 자료 일괄 등록</h3><div class="row">'+btn('한국어','cmcontentlang:ko-KR',language==='ko-KR'?'primary grow':'outline grow')+btn('English','cmcontentlang:en-US',language==='en-US'?'primary grow':'outline grow')+'</div><p>기본 암송 13개 항목의 언어별 본문과 MP3를 관리합니다. 본문과 음성은 배포 권한을 확보한 자료만 등록하세요. 본문은 초안 저장 후 공개합니다. 음성은 즉시 공개 또는 초안 등록을 선택할 수 있습니다.</p><small>본문 공개 '+rows.filter(x=>x.language===language&&x.published).length+' / '+sorted.length+' · 음성 공개 '+sorted.filter(x=>audios.some(a=>a.item_key===x.item_key&&a.language===language&&a.published)).length+' / '+sorted.length+' · 음성 초안 '+audios.filter(a=>a.language===language&&!a.published).length+'개'+'</small>'+(ready?'':'<p class="error">공식 본문 DB 설정(005 SQL)을 적용한 뒤 사용하세요. 음성 업로드는 가능합니다.</p>')+sorted.map((x,i)=>{let t=rows.find(r=>r.item_key===x.item_key&&r.language===language),as=audios.filter(a=>a.item_key===x.item_key&&a.language===language);return '<details class="official-content-row" '+(i===0?'open':'')+'><summary><b>'+esc(language==='en-US'?x.reference_en:x.reference_ko)+'</b><small> · '+(t?(t.published?'본문 공개':'본문 초안'):'본문 미등록')+' · 음성 '+as.length+'개</small></summary><div class="stack">'+(ready?'<label>번역본</label><input data-official-translation="'+esc(x.item_key)+'" maxlength="100" value="'+esc(t?.translation||(language==='en-US'?'ESV':'개역개정'))+'"><label>공식 본문</label><textarea data-official-body="'+esc(x.item_key)+'" rows="5" maxlength="12000">'+esc(t?.body||'')+'</textarea>'+(t?.published?btn('본문 비공개','cmtextunpublish:'+x.item_key,'outline full'):''):'')+'<label>음성 파일 (최대 15MB, MP3 등)</label><input type="file" data-official-audio="'+esc(x.item_key)+'" accept="audio/*,video/webm"><small data-audio-file-info role="status">파일을 선택하지 않았습니다.</small><small>'+as.map(a=>esc(a.title)+' ('+(a.published?'공개':'초안')+')').join(' · ')+'</small></div></details>'}).join('')+'<div class="stack">'+(ready?btn('작성한 본문 일괄 초안 저장','cmtextsave','primary full')+btn('저장된 공식 본문 전체 공개','cmtextpublish','outline full')+btn('이 언어 본문 전체 비공개','cmtextoff','outline full'):'')+btn('선택한 음성 파일 업로드 및 즉시 공개','cmbulkaudio','primary full')+btn('선택한 음성 파일 초안 등록','cmbulkaudiodraft','outline full')+btn('등록된 음성 초안 전체 공개','cmbulkpublish','outline full')+'<p id="official-batch-status" role="status" class="muted"></p><small>음성 공개 후에도 서비스 ON/OFF 설정이 별도로 적용됩니다. 기존 파일 삭제 및 개별 공개 전환은 아래 음성 목록에서 할 수 있습니다.</small></div></section>'
}
const audioMaxBytes=15000000;
function audioSize(file){return file.size===0?'0 B':file.size<1000?file.size+' B':file.size<1000000?(file.size/1000).toFixed(1)+' KB':(file.size/1000000).toFixed(3)+' MB'}
function audioFileError(file){if(!file)return '음성 파일을 선택하세요.';let label=(file.name||'녹음 파일')+' ('+audioSize(file)+')';if(!file.size)return label+' · 빈 파일 (0바이트)';if(file.size>audioMaxBytes)return label+' · 15 MB 초과';return ''}
function showAudioFileInfo(input){let f=input.files?.[0],out=input.nextElementSibling;if(!out?.matches('[data-audio-file-info]'))return;let error=f&&audioFileError(f);out.textContent=f?(error||f.name+' ('+audioSize(f)+') · 업로드 가능'):'파일을 선택하지 않았습니다.';out.style.color=error?'#c2410c':'';input.setAttribute('aria-invalid',error?'true':'false');return error}
function batchStatus(message){let el=$('#official-batch-status');if(el){el.style.whiteSpace='pre-wrap';el.textContent=message}}
document.addEventListener('change',e=>{let el=e.target;if(page==='admin'&&el.matches?.('[data-official-audio],#official-file'))showAudioFileInfo(el)});
async function withOfficialBatch(work){if(officialBatchBusy)return toast('이미 작업 중입니다.');officialBatchBusy=true;let buttons=Array.from(app.querySelectorAll('button[data-act^="cm"]'));buttons.forEach(b=>b.disabled=true);try{if(!await adminCheck())throw Error('관리자 권한이 필요합니다.');await work(onlineCommunity())}catch(e){batchStatus(e.message||'작업에 실패했습니다.');toast('공식 자료 작업 실패')}finally{officialBatchBusy=false;buttons.forEach(b=>b.disabled=false)}}
async function saveOfficialTexts(){const language=adminContentLanguage;return withOfficialBatch(async c=>{let existing=must(await c.from('official_texts').select('*').eq('language',language)),rows=[];for(let el of app.querySelectorAll('[data-official-body]')){let k=el.dataset.officialBody,body=el.value.trim(),translation=app.querySelector('[data-official-translation="'+k+'"]').value.trim();if(!body)continue;if(!translation||translation.length>100||body.length>12000)throw Error('번역본과 본문 길이를 확인하세요.');let old=existing.find(r=>r.item_key===k);if(old&&old.body===body&&old.translation===translation)continue;rows.push({item_key:k,language,translation,body,published:false,updated_at:new Date().toISOString()})}if(!rows.length)return batchStatus('변경된 본문이 없습니다.');if(!confirm(rows.length+'개 본문을 초안으로 저장할까요? 수정한 공개 본문은 다시 공개하기 전까지 비공개됩니다.'))return;must(await c.from('official_texts').upsert(rows,{onConflict:'item_key,language'}));toast(rows.length+'개 본문 초안 저장 완료');await adminPage()})}
async function publishOfficialTexts(){const language=adminContentLanguage;return withOfficialBatch(async c=>{let rows=must(await c.from('official_texts').select('item_key').eq('language',language).eq('published',false));if(!rows.length)return batchStatus('공개할 저장된 초안이 없습니다.');if(language==='en-US'&&!confirm('ESV 원문과 번역본 사용 및 앱 배포 권한을 확인했나요? 확인한 경우에만 공개하세요.'))return;if(!confirm('저장된 본문 초안 '+rows.length+'개를 가입 회원에게 공개할까요? 화면의 미저장 입력은 포함되지 않습니다. 번역본의 배포 권한을 확인하세요.'))return;must(await c.from('official_texts').update({published:true,updated_at:new Date().toISOString()}).eq('language',language).in('item_key',rows.map(r=>r.item_key)));toast(rows.length+'개 본문 공개 완료');await adminPage()})}
async function unpublishOfficialText(id){const language=adminContentLanguage;return withOfficialBatch(async c=>{if(!confirm('이 본문을 비공개로 전환할까요? 이미 회원이 저장한 개인 사본은 유지됩니다.'))return;must(await c.from('official_texts').update({published:false,updated_at:new Date().toISOString()}).eq('item_key',id).eq('language',language));toast('본문 비공개 완료');await adminPage()})}
async function uploadOfficialBatch(publish=true){const language=adminContentLanguage;let selected=Array.from(app.querySelectorAll('[data-official-audio]')).filter(el=>el.files?.length).map(el=>({key:el.dataset.officialAudio,file:el.files[0]}));if(!selected.length)return toast('음성 파일을 선택하세요.');let invalid=selected.filter(x=>audioFileError(x.file));if(invalid.length){for(let el of app.querySelectorAll('[data-official-audio]')){if(invalid.some(x=>x.key===el.dataset.officialAudio)){showAudioFileInfo(el);let details=el.closest('details');if(details)details.open=true}}let message=invalid.length+'개 파일 확인 필요 · 업로드하지 않았습니다.\n'+invalid.map(x=>(language==='en-US'?englishRefs:refs)[Number(x.key.slice(4))]+' — '+audioFileError(x.file)).join('\n');batchStatus(message);return toast(invalid.length+'개 파일에 문제가 있습니다. 아래 상세 목록을 확인하세요.')}if(publish&&!confirm(selected.length+'개 음성을 업로드하고 즉시 공개할까요? 음성 배포 권한을 확인해 주세요.'))return;return withOfficialBatch(async c=>{let ok=0,failed=[];for(let x of selected){if(page!=='admin')break;let ref=(language==='en-US'?englishRefs:refs)[Number(x.key.slice(4))];batchStatus((ok+failed.length+1)+' / '+selected.length+' 업로드 중: '+ref);try{await uploadOfficial(x.file,x.key,language,ref+' · 공식 음성',false,publish);ok++}catch(e){failed.push(ref+': '+(e.message||'실패'))}}if(page!=='admin')return;let message=ok+(publish?'개 음성 등록 및 공개 완료':'개 음성 초안 등록 완료')+(failed.length?' · 실패 '+failed.length+'개: '+failed.join(', '):'');await adminPage();batchStatus(message);toast(ok+(publish?'개 음성 공개 완료':'개 음성 초안 등록 완료'))})}
async function publishOfficialAudioBatch(){const language=adminContentLanguage;return withOfficialBatch(async c=>{let rows=must(await c.from('official_audio').select('id').eq('language',language).eq('published',false));if(!rows.length)return batchStatus('공개할 음성 초안이 없습니다.');if(!confirm(rows.length+'개 저장된 음성 초안을 모두 공개할까요? 음성 배포 권한을 확인해 주세요. 공식 음성 서비스가 활성화되어야 일반 회원에게 표시됩니다.'))return;must(await c.from('official_audio').update({published:true}).eq('language',language).in('id',rows.map(r=>r.id)));toast(rows.length+'개 음성 공개 완료');await adminPage()})}
async function unpublishLanguage(){const language=adminContentLanguage;return withOfficialBatch(async c=>{if(!confirm('선택한 언어의 공식 본문 전체를 비공개로 변경할까요? 개인 학습 기록과 노트는 유지됩니다.'))return;must(await c.from('official_texts').update({published:false,updated_at:new Date().toISOString()}).eq('language',language));toast('공식 본문 비공개 완료');await adminPage()})}
async function importOfficialTexts(){if(preferences().scripture==='en-US')return refreshSharedTexts(true);if(isGuest||!window.YES_CLIENT||!navigator.onLine)return toast('온라인 회원 로그인이 필요합니다.');let c=onlineCommunity(),result=await c.from('official_texts').select('item_key,language,translation,body').eq('published',true).eq('language','ko-KR');if(result.error)return toast('공식 본문을 불러올 수 없습니다.');let rows=result.data.filter(r=>{let x=item(r.item_key);return x?.plan==='yes'&&!x.text.trim()&&typeof r.body==='string'&&r.body.trim()});if(!rows.length)return toast('가져올 공식 본문이 없거나 이미 입력되었습니다.');if(!confirm('공식 본문 '+rows.length+'개를 빈 항목에 가져올까요? 기존 본문 및 학습 기록은 유지됩니다.'))return;let n=0;for(let r of rows){let x=item(r.item_key);if(!x||x.plan!=='yes'||x.text.trim())continue;x.text=r.body;x.translation=r.translation;x.lang=r.language;x.version++;delete db.reviews[x.id];n++}save();if(page==='detail')detail();toast(n+'개 공식 말씀 등록 완료')}


/* Shared official curriculum: public read of published rows only. */
let sharedStatus='공식 말씀 확인 중…',sharedBusy=false,sharedViewId=null,sharedLast=0;
const sharedCacheKey='yes-word-official-ko-v1';
let verseAudioUrl=null,verseAudioRequest=0,verseAudioPending=0,verseAudioTrackKey='';
function clearVerseSource(player){if(player){player.onplay=player.onpause=player.onended=player.onerror=null;player.pause();player.removeAttribute('src');player.load();player.hidden=true}if(verseAudioUrl){URL.revokeObjectURL(verseAudioUrl);verseAudioUrl=null}verseAudioTrackKey=''}
function releaseVerseAudio(){verseAudioRequest++;verseAudioPending=0;clearVerseSource(document.getElementById('verse-audio'))}
async function prepareVerseAudio(x,refresh=false){
 let player=$('#verse-audio'),button=$('#verse-listen'),status=$('#verse-audio-status');if(!player||!button||!status||verseAudioPending||(!player.paused&&refresh))return;
 let request=++verseAudioRequest;verseAudioPending=request;
 const current=()=>request===verseAudioRequest&&page==='sharedview'&&sharedViewId===x.id&&player.isConnected;
 if(!refresh||!verseAudioTrackKey){button.disabled=true;button.textContent='음성 확인 중…';status.textContent=''}
 try{
 let tracks=await loadMainTracks();if(!current())return;let track=tracks.get(x.id+'|'+x.lang);
 if(!track){clearVerseSource(player);button.textContent='음성 준비 중 · 다시 확인';button.disabled=false;button.onclick=()=>prepareVerseAudio(x,true);status.textContent='아직 재생 가능한 공식 녹음이 없습니다.';return}
 let key=track.id+'|'+track.object_path;
 if(key===verseAudioTrackKey&&player.getAttribute('src'))return;
 if(!player.paused)return;
 let blob=await officialBlob(track);if(!current()||!player.paused)return;if(!blob?.size)throw Error('빈 음성 파일');
 clearVerseSource(player);verseAudioUrl=URL.createObjectURL(blob);verseAudioTrackKey=key;player.src=verseAudioUrl;player.playbackRate=db.audio.rate;player.preload='auto';
 button.textContent='▶ 말씀 듣기';button.disabled=false;status.textContent='공식 말씀 음성';
 player.onplay=()=>{button.textContent='Ⅱ 일시정지';status.textContent='공식 말씀 재생 중';player.hidden=false};
 player.onpause=()=>{button.textContent='▶ 말씀 듣기';status.textContent='공식 말씀 음성'};
 player.onended=()=>{button.textContent='▶ 다시 듣기';status.textContent='재생 완료';if(Number.isFinite(player.duration)){db.listening+=Math.round(player.duration);save()}};
 player.onerror=()=>{if(!player.isConnected||sharedViewId!==x.id)return;verseAudioTrackKey='';status.textContent='음성을 재생하지 못했습니다. 다시 연결해 주세요.';button.textContent='다시 연결';button.disabled=false;button.onclick=()=>prepareVerseAudio(x,true)};
 button.onclick=()=>{if(!player.paused){player.pause();return}if(player.ended)player.currentTime=0;player.hidden=false;player.play().catch(()=>{if(player.isConnected)status.textContent='재생 버튼을 다시 눌러주세요.'})};
 }catch(e){if(!current())return;if(verseAudioTrackKey&&player.getAttribute('src'))return;status.textContent='음성 연결에 실패했습니다. 다시 시도해 주세요.';button.textContent='다시 연결';button.disabled=false;button.onclick=()=>prepareVerseAudio(x,true)}
 finally{if(verseAudioPending===request)verseAudioPending=0}
}
let visibleAudioBusy=false;
async function refreshVisibleAudio(){
 if(!navigator.onLine||document.hidden)return;
 if(page==='sharedview'){let x=item(sharedViewId);if(x)return prepareVerseAudio(x,true);return}
 if(!['listen','official'].includes(page)||visibleAudioBusy)return;
 let p=page;visibleAudioBusy=true;try{let tracks=await loadMainTracks();if(page!==p)return;
 if(p==='listen'){let entry=$('#official-entry'),info=$('#audio-source-info');if(entry)entry.innerHTML=officialEnabled&&!isGuest?btn('공식 말씀 음성','goto:official','outline full'):'';if(info)info.textContent=officialEnabled?'공식 녹음 '+Array.from(tracks.values()).filter(a=>a.language===preferences().scripture).length+'개 등록 · AI가 읽어주는 음성 준비 중':'공식 음성 서비스가 현재 제공되지 않습니다.'}
 if(p==='official'&&!officialActive&&!document.activeElement?.matches('select')&&$('#official-status')){let before=officialRows.map(a=>a.id).sort().join('|'),after=Array.from(tracks.values()).map(a=>a.id).sort().join('|');if(before!==after)await officialPage()}
 }catch(e){console.warn('Official audio refresh failed',e)}finally{visibleAudioBusy=false}
}
function refreshOnReturn(){refreshSharedTexts(true);refreshVisibleAudio()}

function sharedView(id){let x=item(id);currentPlan='yes';if(!x||x.plan!=='yes')return go('detail');if(page!=='sharedview'){stopAllPlayback();page='sharedview';history.pushState({yesPage:page},'')}else releaseVerseAudio();sharedViewId=id;let verses=db.items.filter(v=>v.plan==='yes').sort((a,b)=>a.lesson-b.lesson),at=verses.findIndex(v=>v.id===id),prev=verses[at-1],next=verses[at+1];app.innerHTML=btn('← 새일꾼반','goto:detail','outline')+heading('Scripture',x.ref)+languageQuick()+'<section class="card scripture-reading"><div class="row between scripture-toolbar"><small>'+esc(x.translation)+'</small><button type="button" id="verse-listen" class="outline" disabled>음성 확인 중…</button></div><p class="verse scripture-text">'+esc(x.text||'공식 본문 준비 중')+'</p><audio id="verse-audio" controls preload="none" hidden></audio><p id="verse-audio-status" class="muted" role="status" aria-live="polite"></p></section>'+notePanel(x)+(inStudy(x)?btn('암송 시작','startitem:'+x.id,'primary full',x.text?'':'disabled'):'<p class="muted">미리 보기 · 이번 주 학습 및 누적 복습 범위는 그대로 유지됩니다.</p>')+'<div class="row">'+(prev?btn('← 이전 말씀','sharedview:'+prev.id,'outline grow'):'')+(next?btn('다음 말씀 →','sharedview:'+next.id,'outline grow'):'')+'</div>';prepareVerseAudio(x)}
function applySharedTexts(rows){let lang=preferences().scripture,by=new Map(rows.filter(r=>officialIds.has(r.item_key)&&r.language===lang&&typeof r.body==='string'&&r.body.trim()).map(r=>[r.item_key,r]));let changed=normalizeCurriculum(db);for(let i of activeKeys){let id='yes-'+i,r=by.get(id),x=item(id);if(!x||x.plan!=='yes')continue;let previousLang=x.lang==='en-US'?'en-US':'ko-KR',variants=x.languageVersions&&typeof x.languageVersions==='object'?x.languageVersions:{};variants[previousLang]={body:x.text,version:Number(x.version)||1};let body=r?.body||'',tr=r?.translation||(lang==='en-US'?'ESV':'개역개정'),prior=variants[lang],v=prior?prior.version+(prior.body!==body?1:0):1,reference=refLabel(id,lang);if(x.text!==body||x.translation!==tr||x.lang!==lang||x.ref!==reference||x.version!==v){if(x.text&&x.text!==body&&!x.officialShared)x.revisions=[...(x.revisions||[]),{text:x.text,ref:x.ref,version:x.version,time:Date.now()}];x.text=body;x.translation=tr;x.lang=lang;x.ref=reference;x.version=v;changed=true}variants[lang]={body,version:v};x.languageVersions=variants;x.officialShared=true}if(!plan('yes')){db.plans.unshift({id:'yes',title:'새일꾼반'});changed=true}if(changed)save();sharedStatus=by.size+' / '+activeKeys.length+' 공식 본문 등록';return changed}
async function refreshWeeklyConfig(){if(!navigator.onLine)return false;try{let rows=await guestOfficialFetch('rest/v1/yw_weekly_settings?select=focus_from,focus_through&singleton=eq.true');let w=rows[0];if(!w||!Number.isInteger(w.focus_from)||!Number.isInteger(w.focus_through)||w.focus_from<1||w.focus_through>13||w.focus_from>w.focus_through)return false;let changed=w.focus_from!==weeklyConfig.from||w.focus_through!==weeklyConfig.through;weeklyConfig={from:w.focus_from,through:w.focus_through};localStorage.setItem('yw-weekly-public',JSON.stringify(weeklyConfig));return changed}catch{return false}}
function weeklyAdminPanel(){return '<section class="card stack"><h3>현재 수업 진도 · '+classWeek()+'주차</h3><small>수업 진도 따라가기를 선택한 회원과 게스트에게 적용됩니다. 개인 진도는 유지됩니다.</small><label for="admin-class-week">일정표 기준 주차</label><select id="admin-class-week">'+options(classSchedule.map(w=>[w.week,w.week+'주차 · '+(w.from===w.through?w.from:w.from+'~'+w.through)+'과']),classWeek())+'</select>'+btn('선택 주차 적용','weekadminschedule','primary full')+'<details><summary>과 범위 직접 설정</summary><label>시작 과</label><select id="admin-week-from">'+options(Array.from({length:13},(_,i)=>[i+1,(i+1)+'과']),weeklyConfig.from)+'</select><label>마지막 과</label><select id="admin-week-through">'+options(Array.from({length:13},(_,i)=>[i+1,(i+1)+'과']),weeklyConfig.through)+'</select>'+btn('주간 범위 저장','weekadminsave','primary full')+'</details>'+schedulePanel()+'</section>'}
async function saveWeeklyConfig(useSchedule=false){if(isGuest||!await adminCheck())return toast('관리자 전용입니다.');let chosen=classSchedule[Number($('#admin-class-week').value)-1],from=useSchedule?chosen.from:Number($('#admin-week-from').value),through=useSchedule?chosen.through:Number($('#admin-week-through').value);if(from>through)return toast('시작 과가 마지막 과보다 클 수 없습니다.');must(await onlineCommunity().from('yw_weekly_settings').update({focus_from:from,focus_through:through}).eq('singleton',true).select('focus_from,focus_through').single());await refreshWeeklyConfig();toast('주간 학습 범위 변경 완료');return adminPage()}
async function refreshSharedTexts(force=false){if(sharedBusy||(!force&&Date.now()-sharedLast<15000))return;if(!navigator.onLine){sharedStatus='오프라인 · 마지막으로 저장된 공식 말씀';return}sharedBusy=true;try{let weeklyChanged=await refreshWeeklyConfig(),wasEnglishReady=englishReady();let rows;if(window.YES_CLIENT){let r=await window.YES_CLIENT.from('official_texts').select('item_key,language,translation,body').eq('published',true);if(r.error)throw r.error;rows=r.data}else{let r=await fetch('https://nheaxjxixixhmhxinqlt.supabase.co/rest/v1/official_texts?select=item_key,language,translation,body&published=eq.true',{headers:{apikey:'sb_publishable_ORcSnStmZXAuyRxrqtLOTA_ZjJz7naH'},cache:'no-store'});if(!r.ok)throw Error('공식 말씀 연결 실패');rows=await r.json()}if(!Array.isArray(rows))throw Error('본문 형식 오류');localStorage.setItem(sharedCacheKey,JSON.stringify(rows));sharedLast=Date.now();if(['session','record','edit','bulkpage','admin','official','listen'].includes(page)||audioState.active||($('#verse-audio')&&!$('#verse-audio').paused)||document.activeElement?.matches('[data-verse-note],#week-select'))return;let changed=applySharedTexts(rows);if((changed||weeklyChanged||wasEnglishReady!==englishReady(rows))&&['home','plans','detail','study','sharedview'].includes(page))render();let el=$('#shared-text-status');if(el)el.textContent=sharedStatus}catch(e){sharedStatus='공식 말씀 연결 실패 · 저장된 본문 유지';let el=$('#shared-text-status');if(el)el.textContent=sharedStatus}finally{sharedBusy=false}}
try{let cached=JSON.parse(localStorage.getItem(sharedCacheKey));if(Array.isArray(cached))applySharedTexts(cached)}catch{}
window.addEventListener('focus',refreshOnReturn);window.addEventListener('online',refreshOnReturn);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshOnReturn()});setInterval(refreshVisibleAudio,10000);


function issuePage(){app.innerHTML=btn('← 돌아가기','goto:my','outline')+heading('Support','Report Issue')+'<section class="card stack"><p>사용 중 발견한 오류나 개선 의견을 보내주세요. 비밀번호, 개인정보 또는 민감한 내용은 입력하지 마세요.</p><form id="issue-form" class="stack"><label>유형</label><select id="issue-category">'+options([['bug','기능 오류'],['audio','음성 / 재생'],['scripture','성경 본문'],['login','로그인'],['other','기타 / 개선 의견']],'bug')+'</select><label>상세 내용</label><textarea id="issue-body" rows="6" minlength="5" maxlength="2000" required placeholder="어떤 화면에서 어떤 문제가 발생했는지 알려주세요."></textarea><button class="primary full" type="submit">제출하기</button><p class="muted" id="issue-status" role="status"></p></form></section>';$('#issue-form').onsubmit=async e=>{e.preventDefault();let f=e.currentTarget,b=f.querySelector('button'),out=$('#issue-status'),body=$('#issue-body').value.trim();if(body.length<5)return toast('5자 이상 입력하세요.');b.disabled=true;out.textContent='전송 중…';try{let r=await fetch('https://nheaxjxixixhmhxinqlt.supabase.co/rest/v1/yw_issue_reports',{method:'POST',headers:{apikey:'sb_publishable_ORcSnStmZXAuyRxrqtLOTA_ZjJz7naH','Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify({category:$('#issue-category').value,body,app_version:'0.32'})});if(!r.ok)throw Error();f.reset();out.textContent='접수되었습니다. 감사합니다.';toast('Report Issue 접수 완료')}catch{out.textContent='전송하지 못했습니다. 인터넷 연결을 확인하고 다시 시도해 주세요.'}finally{b.disabled=false}}}
async function issueReports(){app.innerHTML=btn('← 관리자','goto:admin','outline')+heading('Support','접수된 오류')+'<p>불러오는 중…</p>';try{if(!await adminCheck())throw Error('관리자 전용');let rows=must(await onlineCommunity().from('yw_issue_reports').select('category,body,app_version,created_at').order('created_at',{ascending:false}).limit(100));if(page!=='issuereports')return;app.innerHTML=btn('← 관리자','goto:admin','outline')+heading('Support','접수된 오류')+(rows.length?rows.map(r=>'<section class="card"><small>'+esc(r.category)+' · '+esc(r.app_version)+' · '+esc(cmDate(r.created_at))+'</small><p style="white-space:pre-wrap">'+esc(r.body)+'</p></section>').join(''):'<section class="card">접수된 오류가 없습니다.</section>')}catch(e){if(page==='issuereports')app.innerHTML=btn('← 관리자','goto:admin','outline')+heading('Support','접수된 오류')+'<p>'+esc(e.message||'조회 실패')+'</p>'}}
function notePanel(x){return '<div class="stack" style="margin-top:14px"><label for="note-'+esc(x.id)+'">나의 묵상 노트</label><textarea id="note-'+esc(x.id)+'" data-verse-note="'+esc(x.id)+'" rows="3" maxlength="10000" placeholder="말씀을 통해 느낀 점, 기도 제목 등을 적어보세요.">'+esc(x.notes||'')+'</textarea><small class="muted">개인 노트 · 자동 저장</small></div>'}
function weekPanel(){return progressSelector()+'<p class="muted">1~'+currentWeek()+'과까지 누적 학습합니다.</p>'+schedulePanel()}
function schedulePanel(){return '<details class="card"><summary>수업 일정표 · 12주</summary>'+classSchedule.map(w=>(w.week===5?'<p class="muted">— BREAK 방학 —</p>':'')+'<div style="border-top:1px solid var(--line);padding:10px 0"><b>'+w.week+'주차 · '+(w.from===w.through?w.from:w.from+'~'+w.through)+'과</b><br><small>'+esc(db.items.filter(x=>x.plan==='yes'&&x.lesson>=w.from&&x.lesson<=w.through).map(x=>x.ref).join(' / '))+'</small>'+(w.reading?'<p class="muted">'+esc(w.reading)+'</p>':'')+'</div>').join('')+'</details>'}
function futureWeeks(homePreview=false){let xs=db.items.filter(x=>x.plan==='yes'&&!inStudy(x)).sort((a,b)=>a.lesson-b.lesson);if(!xs.length)return '';const row=x=>'<div class="row between" style="padding:10px 0;border-top:1px solid var(--line)"><div><small>'+x.lesson+'과</small><h3 style="margin:4px 0">'+esc(x.ref)+'</h3></div>'+btn('말씀 보기 · 듣기','sharedview:'+x.id,'outline',x.text?'':'disabled')+'</div>';return '<section class="card stack"><h3>앞으로 배울 말씀</h3><small class="muted">수업 진도를 변경하지 않고 미리 읽고 들을 수 있어요.</small>'+(homePreview?row(xs[0]):'')+'<details '+(homePreview?'':'open')+'><summary>전체 예정 말씀 ('+xs.length+'개)</summary>'+xs.map(row).join('')+'</details></section>'}
document.addEventListener('input',e=>{let el=e.target;if(!el.matches?.('[data-verse-note]'))return;let x=item(el.dataset.verseNote);if(x){x.notes=el.value.slice(0,10000);save()}});
function addIssueFooter(){if(document.getElementById('issue-footer'))return;let f=document.createElement('footer');f.id='issue-footer';f.style.cssText='text-align:center;padding:16px 12px 100px;';let b=document.createElement('button');b.className='outline';b.textContent='Report Issue';b.dataset.go='issue';f.append(b);app.after(f)}

addIssueFooter();
new MutationObserver(()=>localizeChrome()).observe(app,{childList:true,subtree:true,characterData:true});
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.go)go(b.dataset.go);if(b.dataset.act)Promise.resolve(action(b.dataset.act)).catch(err=>{console.error(err);toast('작업 중 오류가 발생했습니다.')})});history.replaceState({yesPage:page},'');window.addEventListener('popstate',e=>go(e.state?.yesPage||'home',true));window.addEventListener('pagehide',stopAllPlayback);document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO'&&e.target!==mainAudio){stopAudio();document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause()})}},true);render();refreshSharedTexts(true);if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(console.warn);
